// Parse a date or date-range out of a command query. Handles "12–15 Aug",
// "aug 12-15", "12 aug" (check-in only), "12/08[/2026]", ISO, and the relatives
// "tonight/today/tomorrow", "this/next weekend", "this/next week". Returns
// { from, to } ISO (to may be null) or null when nothing date-like is present.
function cmdkParseDates(q, today) {
    const t = today || todayDashed();
    const d0 = new Date(t + 'T00:00:00');
    const iso = (dt) => `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, '0')}-${String(dt.getDate()).padStart(2, '0')}`;
    const addOn = (dt, n) => { const x = new Date(dt); x.setDate(x.getDate() + n); return x; };
    const MON = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
    const monIdx = (s) => MON.indexOf(s.slice(0, 3));
    // Roll to next year when the month is past OR it's THIS month but the day
    // already went by — a booking date always means the future, so "5 July"
    // asked on 17 July is next July, not a past date the quote/price guards
    // then silently reject. A bare whole-month (no day) keeps month-only logic.
    const yearFor = (mi, day) => d0.getFullYear() + (mi < d0.getMonth() || (mi === d0.getMonth() && day != null && day < d0.getDate()) ? 1 : 0);
    const upcoming = (dow) => { const x = new Date(d0); x.setDate(x.getDate() + ((dow - x.getDay() + 7) % 7)); return x; }; // today if it matches
    const MO = 'jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec';
    let m;
    // "12-15 aug" / "12 to 15 august"
    if ((m = q.match(new RegExp('\\b(\\d{1,2})\\s*(?:-|–|to|until|till|thru)\\s*(\\d{1,2})\\s+(' + MO + ')[a-z]*\\b')))) {
        const mi = monIdx(m[3]), yr = yearFor(mi, +m[1]);
        return { from: iso(new Date(yr, mi, +m[1])), to: iso(new Date(yr, mi, +m[2])) };
    }
    // "aug 12-15"
    if ((m = q.match(new RegExp('\\b(' + MO + ')[a-z]*\\s+(\\d{1,2})\\s*(?:-|–|to|until|till|thru)\\s*(\\d{1,2})\\b')))) {
        const mi = monIdx(m[1]), yr = yearFor(mi, +m[2]);
        return { from: iso(new Date(yr, mi, +m[2])), to: iso(new Date(yr, mi, +m[3])) };
    }
    // "15 aug to 18 aug" (month named on both sides — spans month ends too)
    if ((m = q.match(new RegExp('\\b(\\d{1,2})\\s+(' + MO + ')[a-z]*\\s*(?:-|–|to|until|till|thru)\\s*(\\d{1,2})\\s+(' + MO + ')[a-z]*\\b')))) {
        const mi1 = monIdx(m[2]), mi2 = monIdx(m[4]), day1 = +m[1], day3 = +m[3];
        // Anchor the END to the START's year (+1 only when it genuinely wraps past
        // year-end), never an independent yearFor for each side: computing y2 on its
        // own rolled the END back to this year while yearFor pushed the START to next
        // year (start day just gone, end day not) → a reversed cross-year range, which
        // made the dated price command save the wrong single night.
        const y1 = yearFor(mi1, day1);
        const y2 = mi2 < mi1 || (mi2 === mi1 && day3 < day1) ? y1 + 1 : y1;
        return { from: iso(new Date(y1, mi1, day1)), to: iso(new Date(y2, mi2, day3)) };
    }
    // single "12 aug" or "aug 12" → check-in only
    if ((m = q.match(new RegExp('\\b(\\d{1,2})\\s+(' + MO + ')[a-z]*\\b'))) || (m = q.match(new RegExp('\\b(' + MO + ')[a-z]*\\s+(\\d{1,2})\\b')))) {
        const dayStr = /^\d/.test(m[1]) ? m[1] : m[2];
        const monStr = /^\d/.test(m[1]) ? m[2] : m[1];
        const mi = monIdx(monStr), yr = yearFor(mi, +dayStr);
        return { from: iso(new Date(yr, mi, +dayStr)), to: null };
    }
    if ((m = q.match(/\b(\d{4})-(\d{2})-(\d{2})\b/))) return { from: `${m[1]}-${m[2]}-${m[3]}`, to: null };
    if ((m = q.match(/\b(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?\b/))) {
        const day = +m[1], mon = +m[2];
        // Bound the fields — "08/13" is not 8 January next year (month 13 rolling
        // over). An out-of-range DD/MM isn't a date; fall through, don't invent one.
        if (day >= 1 && day <= 31 && mon >= 1 && mon <= 12) {
            const yr = m[3] ? (m[3].length === 2 ? 2000 + +m[3] : +m[3]) : d0.getFullYear();
            return { from: iso(new Date(yr, mon - 1, day)), to: null };
        }
    }
    // bare "in august" / "for september" — the WHOLE month (checkout-style end).
    // Reached only when no day-level pattern above matched.
    if ((m = q.match(new RegExp('\\b(?:in|for|over)\\s+(' + MO + ')[a-z]*\\b')))) {
        const mi = monIdx(m[1]), yr = yearFor(mi);
        return { from: iso(new Date(yr, mi, 1)), to: iso(new Date(yr, mi + 1, 1)) };
    }
    if (/\bnext weekend\b/.test(q)) { const f = addOn(upcoming(6), 7); return { from: iso(f), to: iso(addOn(f, 2)) }; }
    if (/\b(this )?weekend\b/.test(q)) { const f = upcoming(6); return { from: iso(f), to: iso(addOn(f, 2)) }; }
    if (/\btomorrow\b/.test(q)) { const f = addOn(d0, 1); return { from: iso(f), to: iso(addOn(f, 1)) }; }
    if (/\b(tonight|today)\b/.test(q)) return { from: iso(d0), to: iso(addOn(d0, 1)) };
    if (/\bnext week\b/.test(q)) { const f = addOn(upcoming(1), 7); return { from: iso(f), to: iso(addOn(f, 7)) }; }
    if (/\bthis week\b/.test(q)) { const f = upcoming(1); return { from: iso(f), to: iso(addOn(f, 7)) }; }
    return null;
}
// First booking/block occupying [from, to) on a cottage — the calendar truth
// behind every booking command and quote. excludeId skips the booking being
// moved so it never clashes with itself.
function cmdkBookClash(pk, from, to, excludeId) {
    if (!pk || !from || !to) return null;
    const b = (dbBookings[pk] || []).find((o) => o.id !== excludeId && o.checkIn && o.checkOut && o.checkIn < to && o.checkOut > from);
    if (b) return { name: b.name || 'a guest', checkIn: b.checkIn, checkOut: b.checkOut };
    const bl = (((dbBlocks || {})[pk]) || []).find((x) => x.checkIn && x.checkOut && x.checkIn < to && x.checkOut > from);
    if (bl) return { name: (bl.source && bl.source !== 'owner' ? bl.source + ' booking' : 'an owner block'), checkIn: bl.checkIn, checkOut: bl.checkOut };
    return null;
}
