    let data = null;
    try { data = await apiPost('customers.php', { action: 'directory', q }); } catch (e) { return; }
    if (stamp !== __cmdkCustDirStamp || gen !== __cmdkQueryGen) return; // a newer query moved on
    const custs = (data && data.customers) || [];
