    const today = todayDashed();
    // 0-social — a greeting, thanks or "what can you do" gets a natural reply,
    // not a search. Precise matcher, so real questions never land here.
    try {
        const soc = chbNlgSocial(q);
        if (soc) return [{ type: 'answer', id: 'nlg-' + soc.kind, label: soc.text, wrap: true, sub: soc.kind === 'capability' || soc.kind === 'identity' ? 'Your on-device assistant' : '', run: () => { const el = document.getElementById('cmdk-input'); if (el) { el.value = ''; el.focus(); } cmdkSearch(''); } }];
    } catch (e) {}
    // -1) Natural-language commands — a fully-specified task ("block Jollyboat
    // next weekend", "add booking for Smith 12–15 Aug") wins over everything else
    // and opens the target pre-filled.
    // Tagged at the ONE call site so every current and future command branch is
    // covered — the pin guards filter on `cmd`, and an id-literal filter missed
    // the branches that never set id 'cmdk-command' (review finding).
    try { const cmd = cmdkCommand(q, today); if (cmd) return cmd.map((r) => Object.assign(r, { cmd: true })); } catch (e) {}
    // Business-insight queries take priority over guest-name matching (so "which
    // cottage earns most" is never mistaken for a guest). Defined once, used by
    // the insights branch AND to suppress the named-guest handler.
    // NB `which (cottage|month)` is QUALIFIED with an earnings/performance word — a
    // bare "which cottage …" (e.g. "which cottage has a hot tub") is a FEATURE
    // question, not an insight, and must not enter this section (which always emits
    // a figure). Audit finding: the bare form false-answered feature questions.
    // NB `best`/`top` are dropped from the bare-`which cottage` clause — "which
    // cottage is best for families/dogs/a couple" is a FEATURE question, not an
    // earnings one, and was wrongly answered with a revenue figure. A money noun
    // must follow (earn/make/most/money/revenue/income/perform/profit/busiest),
    // and "top earner/earning" is caught by the top-earner sub-branch below.
    const INSIGHTS_RE = /\brevenue\b|\bincome\b|\bearn(ed|ings?|ing)?\b|\btakings?\b|\bturnover\b|\bgross\b|occupanc|occupied|\bnights? (booked|sold)\b|how many nights|average (rate|price|nightly)|\bavg\b|busiest|quietest|best month|worst month|which (cottage|property|house|month).{0,24}(earn|make|most|perform|money|revenue|income|busiest|profit|lucrative)|top cottage|how.?s business|how am i doing|\bperformance\b|how much (did i |have i |i )?(make|made|earn|take)|average (stay|length)|length of stay|how long do (guests|people)|typical (stay|visit)|repeat (guest|customer|visitor)|returning (guest|customer)|\brebook|guests? (who |that )?(come|came|keep coming) back|\badr\b|fill rate|how.?s trade|state of play|top.?line/;
    // Operational list queries (deposits to return, balances to chase, volume) —
    // like insights, they must beat guest-name matching (a query like "overdue
    // balances" must not be read as guest "Olive Over").
    const OPS_RE = /overdue|to chase|\bchase\b|chasing|behind|balances? (due|to chase|overdue|outstanding)|deposit.{0,14}(return|back|refund|give back)|return.{0,14}deposit|how many (guests|bookings|people|stays)|(guests?|bookings?) (this|last) year/;
    const propName = (k) => (propertyMeta[k] && propertyMeta[k].name) || k || '';
    const flat = [];
    if (typeof dbBookings === 'object' && dbBookings) {
        Object.keys(dbBookings).forEach((pk) => (dbBookings[pk] || []).forEach((b) => flat.push({ pk, b })));
    }
    const addDays = (iso, n) => {
        const d = new Date(iso + 'T00:00:00');
        d.setDate(d.getDate() + n);
        return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    };
    const bk = (pk, b, sub) => ({ type: 'booking', id: b.id, label: b.name || '(no name)', sub, run: () => { closeCmdK(); openBookingHub(b.id); }, actions: cmdkBookingActions(b, pk) });
    const ans = (label, sub, run, chips) => ({ type: 'answer', label, sub, run: run || (() => closeCmdK()), chips });
    // A "Show on calendar" chip (time as a first-class axis) — opens the Today
    // timeline and scrolls it to `iso`.
    const calChip = (iso) => ({ label: 'Show on calendar', run: () => { closeCmdK(); Promise.resolve(tryAccessBackOffice()).then(() => setTimeout(() => { try { tlScrollToDate(iso); } catch (e) {} }, 160)); } });
    const byIn = (a, b) => ((a.b.checkIn || '') < (b.b.checkIn || '') ? -1 : 1);
    const byOut = (a, b) => ((a.b.checkOut || '') < (b.b.checkOut || '') ? -1 : 1);
    // External OTA stays (Airbnb / Vrbo / Booking.com) imported via iCal — anonymous
    // and display-only, so they answer the date questions too but route to Today's
    // calendar (there's no booking hub for an imported block).
    const OTA = { airbnb: 'Airbnb', vrbo: 'Vrbo', bookingcom: 'Booking.com' };
    const otaName = (s) => OTA[s] || (s ? s.charAt(0).toUpperCase() + s.slice(1) : 'External');
    const blocks = [];
    if (typeof dbBlocks === 'object' && dbBlocks) {
        Object.keys(dbBlocks).forEach((pk) => (dbBlocks[pk] || []).forEach((bl) => blocks.push({ pk, bl })));
    }
    const ext = (pk, bl, sub) => ({ type: 'external', id: 'ext-' + bl.id, label: `${otaName(bl.source)} guest`, sub, run: () => { closeCmdK(); tryAccessBackOffice(); } });
    const byBlkIn = (a, b) => ((a.bl.checkIn || '') < (b.bl.checkIn || '') ? -1 : 1);
    const byBlkOut = (a, b) => ((a.bl.checkOut || '') < (b.bl.checkOut || '') ? -1 : 1);
    // Period parser: "today" (default), "this/next week", "this/next month", or a
    // named month ("in August") → an inclusive [rStart,rEnd] range + a label, so
    // the arrival/departure questions answer for any window, not just today.
    const monthName = (mi) => ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'][mi];
    const d0 = new Date(today + 'T00:00:00');
    const isoOf = (dt) => `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, '0')}-${String(dt.getDate()).padStart(2, '0')}`;
    let rStart = today, rEnd = today, when = 'today';
    const mm = q.match(/\b(january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sept|sep|oct|nov|dec)\b/);
    if (/next month/.test(q)) {
        const s = new Date(d0.getFullYear(), d0.getMonth() + 1, 1), e = new Date(d0.getFullYear(), d0.getMonth() + 2, 0);
        rStart = isoOf(s); rEnd = isoOf(e); when = 'in ' + monthName(s.getMonth());
    } else if (/this month/.test(q)) {
        rEnd = isoOf(new Date(d0.getFullYear(), d0.getMonth() + 1, 0)); when = 'this month';
    } else if (mm) {
        const mi = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'].indexOf(mm[1].slice(0, 3));
        const yr = d0.getFullYear() + (mi < d0.getMonth() ? 1 : 0);
        rStart = isoOf(new Date(yr, mi, 1)); rEnd = isoOf(new Date(yr, mi + 1, 0)); when = 'in ' + monthName(mi);
    } else if (/next week/.test(q)) {
        rStart = addDays(today, 7); rEnd = addDays(today, 14); when = 'next week';
    } else if (/this week|\bweek\b/.test(q)) {
        rEnd = addDays(today, 7); when = 'this week';
    }

    // Named-guest detection — strip the question scaffolding (aux verbs, payment
    // words, date words, month names) and see if what's left names a real guest.
    // Months/period words are stopped so "coming in August" stays a date question
    // rather than matching a guest called "August".
    const STOP = new Set(
        ('have has had i you we me my mine your our they them their it is are was were be been being do did does done ' +
            'who whom whose what when where which why how that this these those there here ' +
            'the a an to for of in on at by with from and or but so still yet already just about please ' +
            'paid pay paying pays payment payments owe owes owed owing balance outstanding money deposit deposits ' +
            'refund refunded refunds return returned returning keep kept charged charge settle settled fully full part ' +
            'booking bookings booked stay stays staying guest guests customer customers visitor visitors reservation reservations ' +
            'today tomorrow tonight yesterday week weeks month months day days upcoming next coming future soon now current currently ' +
            'leaving leave arriving arrive arrives arrival departure departing checkin checkout check ins outs in-house here ' +
            'free available availability vacancy vacant empty spare enquiry enquiries lead leads ' +
            'january february march april may june july august september october november december jan feb mar apr jun jul aug sep sept oct nov dec ' +
            'show find get list tell give all any many much number count how').split(/\s+/),
    );
    const qWords = q.toLowerCase().replace(/[^a-z\s]/g, ' ').split(/\s+/).filter((w) => w.length >= 3 && !STOP.has(w));
    const nameMatch = (b) => {
        if (!b || !b.name) return false;
        const toks = b.name.toLowerCase().split(/\s+/);
        return qWords.some((w) => toks.some((t) => t === w || (w.length >= 4 && (t.startsWith(w) || w.startsWith(t)))));
    };
    const named = qWords.length ? flat.filter((x) => nameMatch(x.b)) : [];
    // The one-line sub under a named guest's row. ORDER MATTERS, because the sub is
    // deliberately single-line and the TAIL is what gets cut: measured on a phone,
    // this row loses 165px, and money · deposit-state · cottage · dates spent that
    // budget on "deposit not yet refunded" while clipping away the cottage and the
    // dates — the two facts that tell two stays apart, which is the sub's whole job
    // when a name returns several. Identity first, replaceable detail last: the
    // deposit's position is one tap away on the hub; "which stay is this" is not.
    // ONE definition, used by both the single-guest row and the multi-stay list —
    // they had a copy each, so fixing one silently left the other wrong.
    const staySub = (pk, b, m) => {
        const bits = [m.money, propName(pk)];
        if (b.checkIn) bits.push(`${fmtDate(b.checkIn)}–${fmtDate(b.checkOut)}`);
        if (m.dep) bits.push(m.dep);
        return bits.join(' · ');
    };
    // A one-line money + deposit summary for a booking, used by the named-guest hit.
    // STILL TO COLLECT IS `bookingDue`, NOT `ps.balance` — see bookingDue(). These
    // four answers were the last on the rental frame, so searching a name read
    // "£700.00 still due" while the hub, Today and the owed answer in the SAME
    // window all said £750.00 (measured; search-test §42). `ps` stays for the
    // RENTAL questions ("who's put a deposit down"). Settled is tested as chbDuties
    // tests it, so this can't newly claim pence due on a booking Today calls done.
    const moneyState = (pk, b) => {
        const ps = paymentSummary(pk, b);
        let gt = null;
        try { gt = bookingDue(pk, b); } catch (e) { chbSwallow(e, 'moneyState-due'); }
        const due = gt || ps;
        const st = b.holdStatus || 'none';
        const settled = due.fullyPaid || due.balance <= 0.5;
        const money = settled ? (due.total > 0.5 ? 'paid in full' : 'nothing to pay') : `${gbp(due.balance)} still due`;
        const dep = st === 'returned' ? 'deposit refunded' : st === 'kept' ? 'deposit kept for damage' : st === 'charged' ? 'deposit not yet refunded' : '';
        return { ps, gt: due, st, money, dep };
    };

    // 0a) Entity context — the record you're LOOKING AT (an open hub) or the one
    //     this palette conversation just SURFACED (__cmdkConvCtx): "email them",
    //     "when do they leave", "how much do they owe" act on THAT record.
    //     Hub context keeps its wide trigger (task words alone suffice on the
    //     record's own page); conversational context requires a real pronoun so
    //     a fresh generic query ("who's paid a deposit") is never hijacked.
    {
        const anaphor = CHB_ANAPHOR_Q.test(q);
        let ent = __cmdkEntity || null;
        if (!ent && anaphor && __cmdkConvCtx && __cmdkConvCtx.type === 'booking' && typeof findBookingById === 'function') {
            const cb = findBookingById(__cmdkConvCtx.id);
            if (cb) ent = { type: 'booking', id: __cmdkConvCtx.id, name: cb.name || 'this guest', b: cb };
        }
        // Cross-page memory: no hub open and this palette didn't surface a record,
        // but you were reading one moments ago on another page — a pronoun
        // ("email them", "their balance") resolves to it. Requires a real pronoun
        // (anaphor), so a fresh generic query is never hijacked by stale context.
        if (!ent && anaphor) { try { ent = cmdkRecentEntity(); } catch (e) {} }
        const trigger = __cmdkEntity ? CHB_ENTITY_TASK_Q.test(q) : anaphor;
        if (ent && trigger) {
            // A question about the record gets a direct ANSWER row first — the
            // action list is the fallback, not the reply.
            if (ent.type === 'booking' && ent.b) {
                const b = ent.b;
                const loc = typeof findBookingLocation === 'function' ? findBookingLocation(ent.id) : null;
                const pk = loc ? loc.propKey : null;
                const go = () => { closeCmdK(); openBookingHub(ent.id); };
                const isWhen = /\bwhen\b|what (day|date|time)/.test(q);
                if (isWhen && /leav|check.?out|depart|go(ing)? home/.test(q) && b.checkOut) {
                    return [ans(`${ent.name} ${b.checkOut > today ? 'leaves' : 'left'} ${fmtDate(b.checkOut)}`, `${b.checkOutTime ? 'Checks out ' + b.checkOutTime + ' · ' : ''}${pk ? propName(pk) : 'This booking'}`, go, [calChip(b.checkOut)])];
                }
                if (isWhen && /arriv|check.?in|come|get here|start/.test(q) && b.checkIn) {
                    return [ans(`${ent.name} ${b.checkIn > today ? 'arrives' : 'arrived'} ${fmtDate(b.checkIn)}`, `${b.checkInTime ? 'Checks in ' + b.checkInTime + ' · ' : ''}${pk ? propName(pk) : 'This booking'}`, go, [calChip(b.checkIn)])];
                }
                if (/\bowe|balance|how much|paid\b/.test(q)) {
                    // The record's OWN answer, asked while standing on its hub —
                    // so the worst of the four to quote a different figure from.
                    const m = moneyState(pk, b);
                    const settled = m.gt.fullyPaid || m.gt.balance <= 0.5;
                    return [ans(
                        settled ? `${ent.name} is paid in full — ${gbp(m.gt.total)}` : `${ent.name} owes ${gbp(m.gt.balance)} of ${gbp(m.gt.total)}`,
                        settled ? 'Nothing outstanding' : `${gbp(m.gt.paid)} paid so far`,
                        go,
                    )];
                }
            }
            const eacts = cmdkEntityActions(ent);
            return [ans(ent.name || 'This record', ent.type === 'booking' ? 'This booking' : 'This enquiry', () => { closeCmdK(); if (ent.type === 'booking') openBookingHub(ent.id); else openEnquiryHub(ent.id); })]
                .concat(eacts.map((a, i) => ({ type: 'action', id: 'entq-' + i, label: a.label, sub: '', run: a.run })));
        }
    }
    // 0a2) Page context — a bare, page-relative query inherits the cottage whose
    //      editor is open, so "its rates", "the photos", "prices", "description"
    //      land on THAT cottage without naming it. (When no cottage is on screen
    //      this falls through, so the words still search globally.)
    try {
        const ctx = cmdkPageContext();
        if (ctx && ctx.cottage && /^\s*(its?|the|this|that)?\s*(rate|rates|price|prices|pricing|fee|fees|photo|photos|gallery|image|images|text|description|details|feature|features|web|website|seo)s?\s*(please|for it|for this one)?\s*$/i.test(q)) {
            const nm = ctx.cottageName || ctx.cottage;
            const sec = /photo|gallery|image/i.test(q) ? 'photos' : /text|descrip|detail|feature/i.test(q) ? 'text' : /web|seo/i.test(q) ? 'web' : 'rates';
            const meta = typeof ACCOM_SECTIONS !== 'undefined' ? ACCOM_SECTIONS.find((s) => s.id === sec) : null;
            return [ans(`${nm} · ${meta ? meta.label : sec}`, 'Open this cottage’s editor', () => { if (typeof cmdkOpenAccomSec === 'function') cmdkOpenAccomSec(ctx.cottage, sec); })];
        }
    } catch (e) {}
    // 0) Actions / "how do I…" — route a task request straight to the thing that
    // does it. Drawn from the shared CMDK_ACTIONS catalog (also fuzzy-searchable
    // by name/synonym in cmdkAll), so "how to add a booking", "change prices",
    // "edit the welcome guide for Jollyboat" all land on the right editor.
    for (const a of cmdkActions(q)) {
        if (a.re && a.re.test(q)) return [a];
    }

    // 0b0) COMPOSED answers — GENERATE a direct English answer to a simple
    // question instead of returning the record that merely looks relevant.
    // Parse (measure words + guest via `named` + cottage/date via chbEntities)
    // → compute over the live data → phrase one sentence, with the record rows
    // beneath it. Precision-first: every measure needs its trigger words AND a
    // resolvable target, otherwise the query falls through to the curated
    // intents and dossiers below exactly as before. (Money questions about a
    // named guest are already composed by 0b — not duplicated here.)
    {
        const ents = (typeof chbEntities === 'function' && chbEntities(q)) || { dateRange: null, prop: null, amount: null };
        // "Friday 24 July" — sentences read (and SPEAK) better with the weekday
        // spelled out; DD/MM/YYYY stays on the record rows beneath.
        const nice = (isoD) => {
            try {
                const dt = new Date(isoD + 'T00:00:00');
                const s = dt.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
                return String(dt.getFullYear()) === today.slice(0, 4) ? s : s + ' ' + dt.getFullYear();
            } catch (e) { return fmtDate(isoD); }
        };
        const rel = (isoD) => {
            const n = Math.round((new Date(isoD + 'T00:00:00') - new Date(today + 'T00:00:00')) / 864e5);
            return n === 0 ? 'today' : n === 1 ? 'tomorrow' : n === -1 ? 'yesterday' : n > 1 ? `in ${n} days` : `${-n} days ago`;
        };
        const stayNights = (b) => (b.checkIn && b.checkOut ? Math.round((new Date(b.checkOut + 'T00:00:00') - new Date(b.checkIn + 'T00:00:00')) / 864e5) : 0);
        const nn = (n, w) => `${n} ${w}${n === 1 ? '' : 's'}`;
        // The guest the question is about: prefer in-house, then the next stay,
        // then the most recent past one. Their other matches ride along below.
        const byRelevance = (a, b2) => {
            const tier = (x) => (isInResidence(x.b) ? 0 : x.b.checkIn >= today ? 1 : 2);
            return tier(a) - tier(b2) || (tier(a) === 2 ? ((a.b.checkIn || '') > (b2.b.checkIn || '') ? -1 : 1) : ((a.b.checkIn || '') < (b2.b.checkIn || '') ? -1 : 1));
        };
        const ranked = named.slice().sort(byRelevance);
        const target = ranked[0] || null;
        const others = ranked.slice(1, 4).map((x) => bk(x.pk, x.b, `${propName(x.pk)} · ${fmtDate(x.b.checkIn)}–${fmtDate(x.b.checkOut)}`));
        const safe = !INSIGHTS_RE.test(q) && !OPS_RE.test(q);

        // WHEN — "when does Bob arrive / leave / check out", "what day is Cara coming".
        if (target && safe && /\bwhen\b|what (day|date|time)/.test(q)) {
            const b = target.b, nm = b.name || 'This guest';
            // DAMAGE-DEPOSIT REFUND timing (owner → guest): "when do I owe Richard
            // his deposit", "when does she get her deposit back". This is the
            // return direction — NOT the guest's payment status — so it's answered
            // from the deposit's hold state, not the balance. The refund happens
            // AFTER checkout. Guarded off the payment direction ("pay/charge").
            if (/\bdeposit\b/.test(q) && /\brefund|return|\bback\b|give|\bowe\b/.test(q) && !/\bpay|paid|charge/.test(q)) {
                const stt = b.holdStatus || 'none';
                const co = b.checkOut;
                const go = () => { closeCmdK(); openBookingHub(b.id); };
                let head;
                if (stt === 'returned') {
                    head = ans(`${nm}’s deposit has been refunded`, `Already returned · ${propName(target.pk)}`, go);
                } else if (stt === 'kept') {
                    head = ans(`${nm}’s deposit was kept for damage — nothing to return`, `Retained, not refunded · ${propName(target.pk)}`, go);
                } else {
                    const gone = co && hasCheckedOut(b);
                    head = ans(
                        gone ? `${nm}’s deposit is due back now` : `You’ll owe ${nm} their deposit back after checkout`,
                        (gone ? `Checked out ${co === today ? 'today' : nice(co)} — return it now` : co ? `After checkout ${nice(co)} (${rel(co)})` : 'After their stay') + ` · ${propName(target.pk)}`,
                        go,
                        co ? [calChip(co)] : [],
                    );
                }
                head.dedupName = (nm || '').toLowerCase().trim();
                head.actions = cmdkBookingActions(b, target.pk);
                return [head].concat(others);
            }
            // "when does Bob pay" is a MONEY question wearing a when — compose
            // the balance + its due point (the balance is collected before the
            // stay), not the arrival date alone.
            if (/\bpay|paid|owe|balance|deposit|refund/.test(q)) {
                const m = moneyState(target.pk, target.b);
                const head = (m.gt.fullyPaid || m.gt.balance <= 0.5)
                    ? ans(`${nm} is paid in full — nothing left to collect`, `${m.dep ? m.dep + ' · ' : ''}${propName(target.pk)}`, () => { closeCmdK(); openBookingHub(b.id); })
                    : ans(
                          `${nm} owes ${gbp(m.gt.balance)} — due before the stay`,
                          `${b.checkIn ? (b.checkIn < today ? 'Stay already started' : `Arrives ${nice(b.checkIn)} (${rel(b.checkIn)})`) + ' · ' : ''}${propName(target.pk)}`,
                          () => { closeCmdK(); openBookingHub(b.id); },
                          b.checkIn ? [calChip(b.checkIn)] : [],
                      );
                head.dedupName = (nm || '').toLowerCase().trim();
                head.actions = cmdkBookingActions(b, target.pk);
                return [head].concat(others);
            }
            const leaving = /leav|check.?out|depart|going home|out\b/.test(q);
            const inHouse = isInResidence(b); // time-aware, not just date-in-range
            let label, sub, iso;
            if (leaving) {
                iso = b.checkOut;
                label = `${nm} ${b.checkOut < today ? 'left' : b.checkOut === today ? 'leaves TODAY' : 'leaves'} ${b.checkOut === today ? '' : nice(b.checkOut)}`.trim();
                sub = `${rel(b.checkOut)} · checkout ${b.checkOutTime || '10:00'} · ${propName(target.pk)}`;
            } else if (inHouse) {
                iso = b.checkIn;
                label = `${nm} is already here — arrived ${nice(b.checkIn)}`;
                sub = `At ${propName(target.pk)} until ${fmtDate(b.checkOut)} (${rel(b.checkOut)})`;
            } else {
                iso = b.checkIn;
                label = `${nm} ${b.checkIn < today ? 'arrived' : b.checkIn === today ? 'arrives TODAY' : 'arrives'} ${b.checkIn === today ? '' : nice(b.checkIn)}`.trim();
                sub = `${rel(b.checkIn)} · ${nn(stayNights(b), 'night')} at ${propName(target.pk)} · out ${fmtDate(b.checkOut)}`;
            }
            const head = ans(label, sub, () => { closeCmdK(); openBookingHub(b.id); }, iso ? [calChip(iso)] : []);
            head.dedupName = (nm || '').toLowerCase().trim();
            head.actions = cmdkBookingActions(b, target.pk);
            return [head].concat(others);
        }

        // HOW LONG — "how long is Bob staying", "how many nights has Cara got".
        // (A NAMED guest beats the occupancy aggregate that shares these words,
        // so only the ops guard applies — not INSIGHTS_RE.)
        if (target && !OPS_RE.test(q) && /how long|how many nights/.test(q)) {
            const b = target.b, n = stayNights(b), nm = b.name || 'This guest';
            const head = ans(
                `${nm} is ${b.checkOut && b.checkOut < today ? 'stayed' : 'staying'} ${nn(n, 'night')}`,
                `${fmtDate(b.checkIn)} → ${fmtDate(b.checkOut)} at ${propName(target.pk)} · ${nn((b.adults || 0) + (b.children || 0) || b.adults || 2, 'guest')}`,
                () => { closeCmdK(); openBookingHub(b.id); },
                b.checkIn ? [calChip(b.checkIn)] : [],
            );
            head.dedupName = (nm || '').toLowerCase().trim();
            return [head].concat(others);
        }

        // CONTACT DETAIL — "what's Bob's email", "Cara's phone number", "do I
        // have an address for Dan". Answers with the VALUE itself; enquirers
        // count too (they aren't bookings yet). "email them" stays with 0a.
        if (/\b(email|e-?mail|phone|mobile|telephone|address|postcode)\b/.test(q)
            && /what|whats|show|tell|give|find|got|have|need|['’]s\s+(email|e-?mail|phone|mobile|telephone|address|postcode|number)|\b[a-z]{3,}s (email|e-?mail|phone|mobile|number|address|postcode)\b/.test(q)
            && !/\b(email|phone|call|text)\s+(them|him|her)\b/.test(q) && safe) {
            let nm = null, rec = null, open = null, where = '';
            if (target) {
                nm = target.b.name; rec = target.b; where = `Booking · ${propName(target.pk)}`;
                open = () => { closeCmdK(); openBookingHub(target.b.id); };
            } else {
                const en = (Array.isArray(enquiries) ? enquiries : []).find((e) => e.name && qWords.some((w) => e.name.toLowerCase().split(/\s+/).some((t) => t === w || (w.length >= 4 && (t.startsWith(w) || w.startsWith(t))))));
                if (en) { nm = en.name; rec = en; where = `Enquiry · ${propName(en.propKey)}`; open = () => { closeCmdK(); openEnquiryHub(en.id); }; }
            }
            if (rec) {
                const want = /phone|mobile|telephone|number/.test(q) ? ['phone', rec.phone] : /address|postcode/.test(q) ? ['address', [rec.address, rec.postcode].filter(Boolean).join(', ')] : ['email', rec.email];
                const restBits = [rec.email && want[0] !== 'email' ? rec.email : '', rec.phone && want[0] !== 'phone' ? rec.phone : ''].filter(Boolean).join(' · ');
                const head = ans(
                    want[1] ? `${nm}’s ${want[0]} is ${want[1]}` : `No ${want[0]} on file for ${nm}`,
                    (restBits ? restBits + ' · ' : '') + where,
                    open,
                );
                head.dedupName = (nm || '').toLowerCase().trim();
                if (target) head.actions = cmdkBookingActions(target.b, target.pk);
                return [head].concat(others);
            }
        }

        // NEXT ARRIVAL — "who's next", "next arrival", "when's the next check-in".
        // ("next week/month/…" stays a date window for the branches below.)
        if (!named.length && safe && (/\bnext(?!\s+(week|month|year|weekend))\b.*\b(arriv\w*|check.?in|guest|booking|stay)\b/.test(q) || /who.?s (coming |arriving |checking in )?next\b(?!\s+(week|month|year|weekend))/.test(q) || /\b(arriv\w*|check(s|ing)?.?in\w*|comes?|coming)\s+next\b(?!\s+(week|month|year|weekend))/.test(q))) {
            const fut = flat.filter((x) => x.b.checkIn && x.b.checkIn >= today).sort(byIn);
            if (!fut.length) return [ans('No upcoming arrivals', 'The calendar is clear from today', () => { closeCmdK(); tryAccessBackOffice(); })];
            const x = fut[0], b = x.b;
            const head = ans(
                `Next arrival: ${b.name || '(no name)'} — ${b.checkIn === today ? 'TODAY' : nice(b.checkIn)}`,
                `${rel(b.checkIn)} · ${nn(stayNights(b), 'night')} at ${propName(x.pk)}`,
                () => { closeCmdK(); openBookingHub(b.id); },
                [calChip(b.checkIn)],
            );
            head.actions = cmdkBookingActions(b, x.pk);
            return [head].concat(fut.slice(1, 4).map((y) => bk(y.pk, y.b, `${propName(y.pk)} · ${fmtDate(y.b.checkIn)} (${rel(y.b.checkIn)})`)));
        }

        // AVAILABILITY over the ASKED window — "is Jollyboat free next weekend",
        // "anything available in August", "is 21a empty tomorrow". A cottage or a
        // date window must be named; the bare "what's free (tonight)" keeps its
        // branch below. Range semantics: single day = that night; a span = the
        // nights from `from` up to checkout on `to`.
        if (safe && !named.length && /\bfree\b|availab|vacan|empty\b/.test(q) && (ents.prop || ents.dateRange)) {
            const from = ents.dateRange ? ents.dateRange.from : today;
            const label = ents.dateRange ? ents.dateRange.label : 'tonight';
            // chbEntities.to is inclusive-last-DAY for week/month/year/named-month
            // (golden-pinned: "August" → Aug 31) but checkout-style for weekend
            // (→ Sunday). As an EXCLUSIVE night bound, the named spans need +1 or
            // the last night is never tested (a booking checking in Aug 31 read
            // as "free in August"). Weekend's .to is already the checkout.
            const nightsEnd = ents.dateRange && ents.dateRange.to > from
                ? (/weekend/.test(label) ? ents.dateRange.to : addDays(ents.dateRange.to, 1))
                : addDays(from, 1);
            const conflictsFor = (k) => flat
                .filter((x) => x.pk === k && x.b.checkIn && x.b.checkOut && x.b.checkIn < nightsEnd && x.b.checkOut > from)
                .map((x) => ({ kind: 'booking', pk: x.pk, b: x.b }))
                .concat(blocks.filter((x) => x.pk === k && x.bl.checkIn && x.bl.checkOut && x.bl.checkIn < nightsEnd && x.bl.checkOut > from).map((x) => ({ kind: 'block', pk: x.pk, bl: x.bl })));
            if (ents.prop) {
                const conf = conflictsFor(ents.prop);
                if (!conf.length) {
                    return [ans(
                        `Yes — ${propName(ents.prop)} is free ${label}`,
                        `${fmtDate(from)} → ${fmtDate(nightsEnd)} · no bookings or blocks`,
                        () => { closeCmdK(); tryAccessBackOffice(); },
                        [calChip(from), { label: 'Add a booking here', run: () => { closeCmdK(); Promise.resolve(tryAccessBackOffice()).then(() => { try { tlAddAt(ents.prop, from); } catch (e) {} }); } }],
                    )];
                }
                const c0 = conf[0];
                const head = ans(
                    `No — ${propName(ents.prop)} is taken ${label}`,
                    c0.kind === 'booking' ? `${c0.b.name || 'A guest'} is booked ${fmtDate(c0.b.checkIn)}–${fmtDate(c0.b.checkOut)}` : `${(c0.bl.source || 'OTA')} block ${fmtDate(c0.bl.checkIn)}–${fmtDate(c0.bl.checkOut)}`,
                    () => { closeCmdK(); tryAccessBackOffice(); },
                    [calChip(from)],
                );
                return [head].concat(conf.filter((c) => c.kind === 'booking').slice(0, 3).map((c) => bk(c.pk, c.b, `${propName(c.pk)} · ${fmtDate(c.b.checkIn)}–${fmtDate(c.b.checkOut)}`)));
            }
            const freeKs = chbFleetKeys().filter((k) => !conflictsFor(k).length);
            return [ans(
                freeKs.length ? `${nn(freeKs.length, 'cottage')} free ${label}` : `Nothing free ${label}`,
                freeKs.length ? freeKs.map(propName).join(', ') + ` · ${fmtDate(from)} → ${fmtDate(nightsEnd)}` : `All cottages have bookings or blocks ${label}`,
                () => { closeCmdK(); tryAccessBackOffice(); },
                [calChip(from)],
            )];
        }

        // QUOTE — "how much for 12–15 aug at jollyboat", "quote 3 nights from 20
        // september, 2 adults 1 child": price the ASKED stay with the live
        // model, check the calendar, and offer the one-tap prefilled booking.
        // Money-INSIGHTS questions ("how much did I earn…") are kept out by the
        // `safe` guard + the future-start requirement; a query with no dates
        // falls through untouched.
        if (safe && !named.length && /\b(quote|how much|price|cost)\b/.test(q) && !/coach|change|set |edit|update/.test(q)) {
            let qFrom = ents.dateRange ? ents.dateRange.from : null;
            // Same inclusive-last-day → checkout correction as the availability
            // branch, so a whole-month quote ("how much for august") prices all
            // 31 nights, not 30. (Specific-date quotes come from cmdkParseDates
            // below, which is already checkout-style.)
            let qTo = ents.dateRange
                ? (ents.dateRange.to > ents.dateRange.from && !/weekend/.test(ents.dateRange.label || '') ? addDays(ents.dateRange.to, 1) : ents.dateRange.to)
                : null;
            const nightsM = q.match(/(\d+)\s*nights?/);
            if (nightsM) {
                // "3 nights from 20 december": the nights word fixes the LENGTH,
                // so a precise day-level parse beats a whole-month entity range.
                const pd = cmdkParseDates(q, today);
                if (pd && pd.from) { qFrom = pd.from; qTo = pd.to || addDays(pd.from, +nightsM[1]); }
                else if (qFrom) qTo = addDays(qFrom, +nightsM[1]);
            } else if (!qFrom) { const pd = cmdkParseDates(q, today); if (pd) { qFrom = pd.from; qTo = pd.to; } }
            if (qFrom && qTo && qTo > qFrom && qFrom >= today) {
                const adults = +(q.match(/(\d+)\s*adults?/) || [])[1] || 2;
                const children = +(q.match(/(\d+)\s*(?:children|kids?|child)\b/) || [])[1] || 0;
                const quoteFor = (k) => {
                    try {
                        const p = priceBreakdown(k, adults, children, qFrom, qTo);
                        if (!p || !isFinite(p.total) || p.total <= 0) return null;
                        return { k, p, clash: cmdkBookClash(k, qFrom, qTo, null) };
                    } catch (e) { return null; }
                };
                const bookRun = (k) => () => { closeCmdK(); cmdkPrefillAddBooking({ propKey: k, checkIn: qFrom, checkOut: qTo }); };
                if (ents.prop) {
                    const x = quoteFor(ents.prop);
                    if (x) {
                        const head = ans(
                            `${gbp(x.p.total)} for ${nn(x.p.nights, 'night')} at ${propName(x.k)}`,
                            `${fmtDate(qFrom)} → ${fmtDate(qTo)} · ${x.clash ? `⚠ taken then (${x.clash.name})` : 'free ✓ · tap to start the booking'} · £${Math.round(x.p.total / x.p.nights)}/night avg${x.p.damagesDeposit ? ` · + ${gbp(x.p.damagesDeposit)} refundable deposit` : ''}`,
                            bookRun(x.k),
                        );
                        const alts = x.clash
                            ? chbFleetKeys().filter((k) => k !== x.k).map(quoteFor).filter((y) => y && !y.clash).slice(0, 3)
                            : [];
                        return [head].concat(alts.map((y) => ans(`${propName(y.k)} is free those dates — ${gbp(y.p.total)}`, 'Same stay · tap to start the booking', bookRun(y.k))));
                    }
                } else {
                    const all = chbFleetKeys().map(quoteFor).filter(Boolean);
                    const free = all.filter((x) => !x.clash);
                    if (all.length) {
                        const cheapest = (free.length ? free : all).slice().sort((a, z) => a.p.total - z.p.total)[0];
                        const head = ans(
                            `From ${gbp(cheapest.p.total)} — ${fmtDate(qFrom)} → ${fmtDate(qTo)}`,
                            `${nn(free.length, 'cottage')} free of ${all.length} · ${adults} adult${adults === 1 ? '' : 's'}${children ? ` + ${children} child${children === 1 ? '' : 'ren'}` : ''}`,
                            bookRun(cheapest.k),
                        );
                        return [head].concat(all.map((x) => ans(
                            `${propName(x.k)} · ${gbp(x.p.total)}${x.clash ? ' · ⚠ taken' : ' · free ✓'}`,
                            x.clash ? `${x.clash.name} is there ${fmtDate(x.clash.checkIn)}–${fmtDate(x.clash.checkOut)}` : 'Tap to start the booking',
                            bookRun(x.k),
                        )));
                    }
                }
            }
        }

        // CAPACITY — "how many people can Jollyboat sleep", "does 21a take kids".
        // The sleep/capacity VERBS are unambiguous alongside a named cottage, so
        // no OPS/INSIGHTS guard — "how many people can X sleep" must beat the
        // guest-volume aggregate that also owns "how many people".
        // `hold`/`fit` are only capacity words WITH people/how-many context — bare
        // \bhold\b stole "does Jollyboat hold my deposit"; bare \bfit\b stole "will
        // the sofa fit in 21a". `sleeps`/`capacity`/`accommodate` are unambiguous.
        if (ents.prop && (/\bsleeps?\b|capacit|accommodat|take (kids|children)/.test(q) || (/\b(hold|fit)\b/.test(q) && /\b(people|guests?|adults?|kids?|children|how many|sleep)\b/.test(q)))) {
            const m = propertyMeta[ents.prop] || {};
            const oc = (typeof occupancyLimits === 'object' && occupancyLimits[ents.prop]) || {};
            const cap = m.maxTotal || m.maxAdults || oc.maxTotal || oc.maxAdults;
            if (cap) {
                const kids = m.maxChildren != null ? m.maxChildren : oc.maxChildren || 0;
                return [ans(
                    `${propName(ents.prop)} sleeps up to ${nn(cap, 'guest')}`,
                    `${nn(m.maxAdults || oc.maxAdults || cap, 'adult')}${kids ? ` + up to ${nn(kids, 'child')}` : ' · no children'}`,
                    () => { closeCmdK(); if (typeof openProperty === 'function') openProperty(ents.prop); },
                )];
            }
        }

        // "THE guest" / "this booking" — a WHEN or HOW-LONG question with NO name
        // still deserves a composed answer when it resolves to ONE salient stay.
        // Works for direct bookings AND OTA blocks (an OTA guest has dates but no
        // check-in time the channel shares). More than one candidate → fall
        // through to the generic list branches below.
        if (!named.length) {
            const askWhen = /\bwhen\b|what time/.test(q) && /\barriv|check.?in|coming|leav|check.?out|depart/.test(q);
            // A HABITUAL phrasing belongs to the average-length-of-stay family and an
            // AGGREGATE one to the nights-booked family — not here. This branch
            // resolves to ONE stay (the soonest, when nobody is in residence), and
            // its words are broad enough to swallow both: "how many nights" + "book"
            // matched "how many nights booked this month", so a core metric question
            // was answered with one guest's booking. Any future stay was enough to
            // trigger it, which is nearly always.
            const askLong = !CHB_STAYLEN_Q.test(q) && !CHB_NIGHTSAGG_Q.test(q) && /how long|how many nights/.test(q) && /\bguest|book|stay|they|them\b/.test(q);
            if (askWhen || askLong) {
                const leaving = /\bleav|check.?out|depart|going home/.test(q);
                const norm = (kind, pk, r) => ({
                    kind, pk, name: kind === 'direct' ? (r.name || 'The guest') : otaName(r.source) + ' guest',
                    chan: kind === 'direct' ? null : otaName(r.source),
                    checkIn: r.checkIn, checkOut: r.checkOut,
                    ci: kind === 'direct' ? (r.checkInTime || '15:00') : null,
                    co: kind === 'direct' ? (r.checkOutTime || '10:00') : null,
                    b: kind === 'direct' ? r : null,
                    open: kind === 'direct' ? (() => { closeCmdK(); openBookingHub(r.id); }) : (() => { closeCmdK(); tryAccessBackOffice(); }),
                });
                const all = flat.map((x) => norm('direct', x.pk, x.b)).concat(blocks.filter((x) => isOtaBlock(x.bl)).map((x) => norm('ota', x.pk, x.bl)));
                let set;
                if (askWhen) {
                    const win = ents.dateRange;
                    const key = leaving ? 'checkOut' : 'checkIn';
                    const to = win ? (win.to > win.from ? win.to : win.from) : null;
                    set = (win ? all.filter((r) => r[key] >= win.from && r[key] <= to) : all.filter((r) => r[key] >= today)).sort((a, b) => (a[key] < b[key] ? -1 : 1));
                } else {
                    const inres = all.filter((r) => (r.kind === 'direct' ? isInResidence(r.b) : r.checkIn <= today && r.checkOut > today));
                    set = inres.length ? inres : all.filter((r) => r.checkIn >= today).sort((a, b) => (a.checkIn < b.checkIn ? -1 : 1)).slice(0, 1);
                }
                if (set.length === 1) {
                    const r = set[0];
                    const nights = Math.round((new Date(r.checkOut + 'T00:00:00') - new Date(r.checkIn + 'T00:00:00')) / 864e5);
                    if (askLong) {
                        const head = ans(`${r.name} is staying ${nn(nights, 'night')}`, `${fmtDate(r.checkIn)} → ${fmtDate(r.checkOut)} at ${propName(r.pk)}`, r.open, [calChip(r.checkIn)]);
                        if (r.b) head.actions = cmdkBookingActions(r.b, r.pk);
                        return [head];
                    }
                    const iso = leaving ? r.checkOut : r.checkIn;
                    const tm = leaving ? r.co : r.ci; // null for OTA
                    const verb = leaving
                        ? (iso < today ? 'left' : iso === today ? 'leaves TODAY' : 'leaves')
                        : (iso < today ? 'arrived' : iso === today ? 'arrives TODAY' : 'arrives');
                    const label = (`${r.name} ${verb} ${iso === today ? '' : nice(iso)}`).replace(/\s+/g, ' ').trim() + (tm ? ` at ${tm}` : '');
                    const head = ans(
                        label,
                        tm
                            ? `${rel(iso)} · ${leaving ? 'checkout' : 'check-in'} ${tm} · ${propName(r.pk)}`
                            : `${rel(iso)} · ${r.chan} doesn’t share a ${leaving ? 'checkout' : 'check-in'} time · ${propName(r.pk)}`,
                        r.open, [calChip(iso)],
                    );
                    if (r.b) head.actions = cmdkBookingActions(r.b, r.pk);
                    return [head];
                }
                // 0 or >1 → the generic arriving/leaving/staying branches answer.
            }
        }
    }

    // 0b) A specific guest by name — "have I refunded John?", "has Mary paid?",
    // "John's booking". Naming a guest wins over the generic intents below: the
    // head answers the money/refund question directly and the row(s) open the hub.
    // (Insight/operational queries are excluded so "which cottage earns most" or
    // "overdue balances" can't be mistaken for a guest name.)
    if (named.length && !INSIGHTS_RE.test(q) && !OPS_RE.test(q)) {
        const rows = named.slice().sort(byIn);
        // A SINGLE matched guest is ONE record — return one rich row, not an answer
        // head twinned with an identical booking row below it (the old shape read as
        // a duplicate). A question ("has X paid?") phrases the answer; a plain name
        // returns the booking row itself. Either way it carries the same chips +
        // quick-actions, and its `dedupName` suppresses a same-guest server twin.
        if (rows.length === 1) {
            const g = rows[0], m = moneyState(g.pk, g.b), nm = g.b.name || 'This guest';
            const go = () => { closeCmdK(); openBookingHub(g.b.id); };
            const chips = [{ label: `${propName(g.pk)} bookings`, q: `${propName(g.pk)} bookings` }].concat(g.b.checkIn ? [calChip(g.b.checkIn)] : []);
            const acts = cmdkBookingActions(g.b, g.pk);
            if (/refund|deposit|owe|paid|balance|\bpay\b|paying|settle|money|owes|owing/.test(q)) {
                let head;
                if (/refund|deposit/.test(q)) {
                    head =
                        m.st === 'returned' ? ans(`Yes — ${nm}’s deposit was refunded`, 'Damage deposit returned', go)
                        : m.st === 'kept' ? ans(`${nm}’s deposit was kept for damage`, 'Retained, not refunded', go)
                        : m.st === 'charged' ? ans(`Not yet — ${nm}’s deposit is still to refund`, 'Charged with their payment; return it after checkout', go)
                        : ans(`No damage deposit on file for ${nm}`, 'Nothing to refund', go);
                } else {
                    head = ans(`${nm} — ${m.money}`, m.ps.fullyPaid ? `Settled up · ${propName(g.pk)}` : `Open the booking to take payment · ${propName(g.pk)}`, go);
                }
                head.chips = chips;
                head.actions = acts;
                head.dedupName = nm.toLowerCase().trim();
                return [head];
            }
            // Plain name → the booking row IS the result (calendar icon, name matched).
            const row = bk(g.pk, g.b, staySub(g.pk, g.b, m));
            row.chips = chips;
            row.dedupName = nm.toLowerCase().trim();
            return [row];
        }
        const stayRows = () => rows.map((x) => {
            const m = moneyState(x.pk, x.b);
            return bk(x.pk, x.b, staySub(x.pk, x.b, m));
        });
        // If every same-name match is the SAME person (one strong identity —
        // email/phone), LEAD with the unified customer (lifetime stats) instead of
        // "N bookings match that name" — the directory's whole point — then list
        // their stays. Two DIFFERENT people who share a name (distinct identities)
        // still get the "pick the guest you mean" disambiguation.
        try {
            if (rows.length >= 2 && new Set(rows.map((x) => chbCustomerKey(x.b))).size === 1) {
                const c = (chbCustomers() || []).find((cc) => cc.key === chbCustomerKey(rows[0].b));
                if (c) {
                    const chead = ans(c.name || rows[0].b.name || 'This guest',
                        `${c.stays.length} stays · ${gbp(c.revenue)} lifetime${c.last ? ' · last ' + fmtDate(c.last) : ''}`,
                        () => openCustomer(c.key));
                    chead._customer = true;
                    chead.dedupName = (c.name || '').toLowerCase().trim();
                    chead.actions = [{ key: 'email', label: 'Email', icon: cmdkActIcon('mail'), run: () => { closeCmdK(); if (c.latestId != null && typeof openBookingEmail === 'function') openBookingEmail(c.latestId); } }];
                    return [chead].concat(stayRows());
                }
            }
        } catch (e) {}
        const head = ans(`${rows.length} bookings match that name`, 'Pick the guest you mean', () => { closeCmdK(); openBookings(); });
        return [head].concat(stayRows());
    }

    // 0b9) SCOPE-BATCH families — reputation, expenses, plans, lapsed,
    // waitlist. DELIBERATELY ABOVE insights: CHB_LAPSED_Q must beat the repeat
    // family's \brebook, and insights' generic tail would otherwise claim any
    // INSIGHTS_RE-shaped query these declined.
    {
        const pn = (k) => (propertyMeta[k] && propertyMeta[k].name) || k || '';
        if (CHB_RATING_Q.test(q)) {
            const rows = (typeof allReviews === 'function' ? allReviews() : []).filter((r) => r && r.stars);
            if (!rows.length)
                return [{ type: 'figure', id: 'rep', label: 'No reviews yet', sub: 'Nothing to average — reviews appear here once approved', run: () => { closeCmdK(); openArea(); settingsOpen('reviews'); } }];
            const st = (r) => Math.max(1, Math.min(5, parseInt(r.stars) || 5));
            const avg = rows.reduce((s, r) => s + st(r), 0) / rows.length;
            const byPk = {};
            rows.forEach((r) => { if (r.prop) (byPk[r.prop] = byPk[r.prop] || []).push(st(r)); });
            const go = () => { closeCmdK(); openArea(); settingsOpen('reviews'); };
            const head = { type: 'figure', id: 'rep', label: `★ ${avg.toFixed(2)} average across ${rows.length} review${rows.length === 1 ? '' : 's'}`, sub: 'Every review shown on the site', run: go };
            return [head].concat(Object.keys(byPk).map((k) => {
                const cAvg = byPk[k].reduce((s, n) => s + n, 0) / byPk[k].length;
                return {
                    type: 'answer', id: 'rep-' + k,
                    label: `${pn(k)} · ★ ${cAvg.toFixed(2)}`,
                    sub: `${byPk[k].length} review${byPk[k].length === 1 ? '' : 's'}`,
                    // Capsule only where it states a safe fact; a low average
                    // gets NONE — the figure already speaks.
                    stcap: byPk[k].length < 5 ? { tone: 'unk', text: 'Few reviews' } : cAvg >= 4.5 ? { tone: 'ok', text: 'Strong' } : null,
                    run: go,
                };
            }));
        }
        if (CHB_EXPENSE_Q.test(q) && ((allExpenses || []).length || __expTried)) {
            const go = () => { closeCmdK(); cmdkOpenAccounts('expenses'); };
            if (!(allExpenses || []).length)
                return [{ type: 'figure', id: 'exp', label: 'No expenses logged yet', sub: 'Log costs under Payments → Expenses and this will add them up', run: go }];
            // The books speak tax years, so this does too — named in the label.
            const y0 = taxYearStartOf(todayDashed());
            const year = /last year/.test(q) ? y0 - 1 : y0;
            const pool = expensesForYear(year);
            const yLbl = `tax year ${year}/${String((year + 1) % 100).padStart(2, '0')}`;
            const cat = (typeof EXPENSE_CATS !== 'undefined' ? EXPENSE_CATS : []).find((c) => q.includes(String(c).toLowerCase()));
            const sum = (xs) => Math.round(xs.reduce((s, x) => s + (parseFloat(x.amount) || 0), 0) * 100) / 100;
            if (cat) {
                const rows = pool.filter((x) => String(x.category || '') === cat);
                return [{ type: 'figure', id: 'exp', label: `${gbp(sum(rows))} on ${String(cat).toLowerCase()} · ${yLbl}`, sub: `${rows.length} expense${rows.length === 1 ? '' : 's'} · ${gbp(sum(pool))} across everything`, run: go }];
            }
            const byCat = {};
            pool.forEach((x) => { const c = String(x.category || 'Other'); byCat[c] = (byCat[c] || 0) + (parseFloat(x.amount) || 0); });
            const ranked = Object.keys(byCat).map((c) => ({ c, v: Math.round(byCat[c] * 100) / 100 })).sort((a, b) => b.v - a.v);
            const head = { type: 'figure', id: 'exp', label: `${gbp(sum(pool))} spent · ${yLbl}`, sub: `${pool.length} expense${pool.length === 1 ? '' : 's'} logged${ranked.length ? ' · biggest: ' + ranked[0].c.toLowerCase() : ''}`, run: go };
            return [head].concat(ranked.slice(0, 5).map((r) => ({ type: 'answer', id: 'exp-' + r.c, label: `${r.c} · ${gbp(r.v)}`, sub: `${Math.round((100 * r.v) / (sum(pool) || 1))}% of the year's spend`, run: go })));
        }
        if (CHB_PLAN_Q.test(q) && typeof chbAutopayRows === 'function') {
            const rows = chbAutopayRows();
            if (!rows.length)
                return [{ type: 'figure', id: 'plan', label: 'No automatic payment plans running', sub: 'Plans start when a guest opts in while paying their deposit', run: () => { closeCmdK(); cmdkOpenAccounts('recent'); } }];
            const head = { type: 'figure', id: 'plan', label: `${rows.length} payment plan${rows.length === 1 ? '' : 's'} running`, sub: rows[0].next ? `Next collection ${fmtDate(rows[0].next)} — ${rows[0].name}, ${gbp(rows[0].fig)}` : 'Collections run on their due dates', run: () => { closeCmdK(); cmdkOpenAccounts('recent'); } };
            return [head].concat(rows.slice(0, 6).map((r) => ({ type: 'answer', id: 'plan-' + r.id, label: `${r.name} · ${gbp(r.fig)}${r.next ? ' on ' + fmtDate(r.next) : ''}`, sub: `${r.prop} · ${r.prog}`, stcap: r.failed ? { tone: 'bad', text: 'Card declined' } : { tone: 'ok', text: 'On track' }, run: () => { closeCmdK(); openBookingHub(r.id, false); } })));
        }
        if (CHB_LAPSED_Q.test(q) && typeof chbCustomers === 'function') {
            const today = todayDashed();
            const cutoff = ukShiftDays(today, -180);
            const lapsed = chbCustomers()
                .filter((c) => c.last && c.last <= cutoff && !c.stays.some((s) => s.checkIn && s.checkIn > today))
                .sort((a, b) => b.revenue - a.revenue);
            const goG = () => { closeCmdK(); openArea(); settingsOpen('guests'); };
            if (!lapsed.length)
                return [{ type: 'figure', id: 'lapsed', label: 'No lapsed guests', sub: 'Everyone who stayed over six months ago either rebooked or is booked in', run: goG }];
            const head = { type: 'figure', id: 'lapsed', label: `${lapsed.length} past guest${lapsed.length === 1 ? '' : 's'} haven’t rebooked`, sub: 'Stayed over six months ago, nothing upcoming — worth a friendly nudge', run: goG };
            return [head].concat(lapsed.slice(0, 6).map((c) => ({
                type: 'guest', id: 'lapsed-' + c.key, _customer: true,
                label: c.name || '(no name)',
                sub: `${c.stays.length} stay${c.stays.length === 1 ? '' : 's'} · ${gbp(c.revenue)} lifetime · last ${fmtDate(c.last)}`,
                actions: c.latestId != null ? [{ key: 'email', label: 'Email', icon: cmdkActIcon('mail'), run: () => { closeCmdK(); if (typeof openBookingEmail === 'function') openBookingEmail(c.latestId); } }] : undefined,
                run: () => openCustomer(c.key),
            })));
        }
        if (CHB_WAITLIST_Q.test(q) && Array.isArray(__wlCache)) {
            const go = () => { closeCmdK(); openArea(); settingsOpen('waitlist'); };
            if (!__wlCache.length)
                return [{ type: 'figure', id: 'wl', label: 'Nobody on the waitlist', sub: 'Guests join it when their dates are taken', run: go }];
            const head = { type: 'figure', id: 'wl', label: `${__wlCache.length} waiting for a space`, sub: 'Told automatically the moment matching dates free up', run: go };
            return [head].concat(__wlCache.slice(0, 6).map((w, i) => ({
                type: 'answer', id: 'wl-' + i,
                label: `${w.name || w.email || 'A guest'}${w.prop_key || w.prop ? ' · ' + pn(w.prop_key || w.prop) : ''}`,
                sub: w.check_in && w.check_out ? `${fmtDate(w.check_in)} – ${fmtDate(w.check_out)}` : 'Any dates — open-ended wait',
                run: go,
            })));
        }
    }

    // 0c) Business insights — revenue, occupancy, nights, average rate, best month,
    // top cottage — computed from the live bookings (locked agreedPrice attributed
    // to the stay's check-in). Rendered as a figure card that opens Payments.
    if (INSIGHTS_RE.test(q)) {
        const dd0 = new Date(today + 'T00:00:00');
        const isoD = (dt) => `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, '0')}-${String(dt.getDate()).padStart(2, '0')}`;
        const dnights = (a, b) => Math.max(0, Math.round((new Date(b + 'T00:00:00') - new Date(a + 'T00:00:00')) / 86400000));
        const total = (b) => (b.agreedPrice && b.agreedPrice.total) || 0;
        const openMoney = () => { closeCmdK(); openAccounts(); };
        const MON3 = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
        // Booked nights come from BOTH paying bookings AND imported OTA guest stays —
        // Airbnb / Vrbo carry no price, only dates, so revenue alone hides them. Owner
        // MAINTENANCE blocks are NOT bookings; isOtaBlock() excludes them (source
        // falsy or 'owner'), so blocked-out dates never count as booking days.
        const otaStays = blocks.filter((x) => isOtaBlock(x.bl)).map((x) => ({ pk: x.pk, b: { checkIn: x.bl.checkIn, checkOut: x.bl.checkOut }, ota: true }));
        // A NAMED cottage scopes every figure in this branch — "jollyboat revenue
        // this year", "occupancy at 21a last month" (and the conversational
        // "just jollyboat" refinement composes exactly these queries).
        let insProp = null;
        try { insProp = (((typeof chbEntities === 'function' && chbEntities(q)) || {}).prop) || null; } catch (e) {}
        const allStays = flat.map((x) => ({ pk: x.pk, b: x.b, ota: false })).concat(otaStays).filter((x) => !insProp || x.pk === insProp);
        const nights = (x) => (x.b.checkIn && x.b.checkOut ? dnights(x.b.checkIn, x.b.checkOut) : 0);
        // Repeat-guest rate — from the unified customer directory (strong identity
        // only, so two different "John Smith"s can never fake a repeat). All-time
        // by nature: loyalty isn't a monthly figure.
        if (/repeat (guest|customer|visitor)|returning (guest|customer)|\brebook|guests? (who |that )?(come|came|keep coming) back/.test(q)) {
            let cust = [];
            try { cust = chbCustomers(); } catch (e) {}
            const withStay = cust.filter((c) => c.stays.length >= 1);
            const rep = cust.filter((c) => c.stays.length >= 2).sort((a, z) => z.stays.length - a.stays.length || z.revenue - a.revenue);
            if (!rep.length) return [{ type: 'figure', id: 'ins', label: 'No repeat guests yet', sub: `${withStay.length} guest${withStay.length === 1 ? '' : 's'} so far — every stay is a first stay`, run: openMoney }];
            const pct = Math.round((100 * rep.length) / (withStay.length || 1));
            const lead = rep[0];
            const head = { type: 'figure', id: 'ins', label: `${rep.length} repeat guest${rep.length === 1 ? '' : 's'} — ${pct}% come back`, sub: `Of ${withStay.length} guest${withStay.length === 1 ? '' : 's'} all-time · ${chbSayFirst(lead.name)} leads with ${lead.stays.length} stays`, run: openMoney };
            return [head].concat(rep.slice(0, 5).map((c) => ({ type: 'answer', id: 'ins-rep-' + c.key, label: `${c.name || 'Unnamed guest'} · ${c.stays.length} stays`, sub: `${c.nights} night${c.nights === 1 ? '' : 's'} · ${gbp(c.revenue)} lifetime`, run: () => { closeCmdK(); try { openCustomer(c.key); } catch (e) {} } })));
        }
        // "busiest / quietest month" ranks by NIGHTS (occupancy, OTA-aware); "best /
        // worst month" ranks by REVENUE (money). Both carry the other figure alongside.
        if (/busiest|best month|quietest|worst month|which month/.test(q)) {
            const byMoney = /best month|worst month/.test(q);
            const yr = /last year/.test(q) ? dd0.getFullYear() - 1 : dd0.getFullYear();
            const rev = Array.from({ length: 12 }, () => 0);
            const nts = Array.from({ length: 12 }, () => 0);
            allStays.forEach((x) => { if (x.b.checkIn && +x.b.checkIn.slice(0, 4) === yr) { const mi = +x.b.checkIn.slice(5, 7) - 1; rev[mi] += total(x.b); nts[mi] += nights(x); } });
            const rankedM = Array.from({ length: 12 }, (_, mi) => ({ mi, rev: rev[mi], nt: nts[mi], v: byMoney ? rev[mi] : nts[mi] })).filter((m) => m.v > 0).sort((a, b) => b.v - a.v);
            if (!rankedM.length) return [{ type: 'figure', id: 'ins', label: `No bookings in ${yr} yet`, sub: 'Nothing to rank', run: openMoney }];
            const quiet = /quietest|worst/.test(q);
            const pick = quiet ? rankedM[rankedM.length - 1] : rankedM[0];
            const figV = (m) => (byMoney ? gbp(m.rev) : `${m.nt} night${m.nt === 1 ? '' : 's'}`);
            const otherV = (m) => (byMoney ? `${m.nt} night${m.nt === 1 ? '' : 's'}` : gbp(m.rev));
            const head = { type: 'figure', id: 'ins', label: `${monthName(pick.mi)}’s your ${quiet ? 'quietest' : 'busiest'} — ${figV(pick)}`, sub: `By ${byMoney ? 'revenue' : 'nights booked'} in ${yr} · ${otherV(pick)}`, run: openMoney };
            return [head].concat(rankedM.slice(0, 6).map((m) => ({ type: 'answer', id: 'ins-m' + m.mi, label: `${monthName(m.mi)} · ${figV(m)}`, sub: `${otherV(m)}`, run: openMoney })));
        }
        // Period for the point-in-time metrics.
        let pStart, pEnd, plabel;
        const nm = q.match(/\b(january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sept|sep|oct|nov|dec)\b/);
        if (/this year/.test(q)) { pStart = `${dd0.getFullYear()}-01-01`; pEnd = `${dd0.getFullYear()}-12-31`; plabel = `in ${dd0.getFullYear()}`; }
        else if (/last year/.test(q)) { const y = dd0.getFullYear() - 1; pStart = `${y}-01-01`; pEnd = `${y}-12-31`; plabel = `in ${y}`; }
        else if (/last month/.test(q)) { const s = new Date(dd0.getFullYear(), dd0.getMonth() - 1, 1), e = new Date(dd0.getFullYear(), dd0.getMonth(), 0); pStart = isoD(s); pEnd = isoD(e); plabel = 'in ' + monthName(s.getMonth()); }
        else if (/next month/.test(q)) { const s = new Date(dd0.getFullYear(), dd0.getMonth() + 1, 1), e = new Date(dd0.getFullYear(), dd0.getMonth() + 2, 0); pStart = isoD(s); pEnd = isoD(e); plabel = 'in ' + monthName(s.getMonth()); }
        else if (nm) {
            // Revenue/occupancy are HISTORICAL — a bare month name means the most
            // recent instance, not this year's future one ("how much did I earn in
            // December" asked in Feb means LAST December, not a £0 future month).
            // An explicit year in the query is honoured as typed.
            const mi = MON3.indexOf(nm[1].slice(0, 3));
            const ym = q.match(/\b(20\d{2})\b/);
            let yr = ym ? +ym[1] : dd0.getFullYear();
            if (!ym && new Date(yr, mi, 1) > dd0) yr--;
            pStart = isoD(new Date(yr, mi, 1)); pEnd = isoD(new Date(yr, mi + 1, 0)); plabel = 'in ' + monthName(mi) + (ym ? ' ' + yr : '');
        }
        else { const s = new Date(dd0.getFullYear(), dd0.getMonth(), 1), e = new Date(dd0.getFullYear(), dd0.getMonth() + 1, 0); pStart = isoD(s); pEnd = isoD(e); plabel = 'this month'; }
        if (insProp) plabel += ` at ${propName(insProp)}`;
        const stays = allStays.filter((x) => x.b.checkIn && x.b.checkIn >= pStart && x.b.checkIn <= pEnd);
        const revenue = stays.reduce((s, x) => s + total(x.b), 0);
        const soldNights = stays.reduce((s, x) => s + nights(x), 0);
        const otaNights = stays.filter((x) => x.ota).reduce((s, x) => s + nights(x), 0);
        // Average nightly rate divides revenue by the PAYING nights only — OTA nights
        // carry no price, so folding them in would fake-deflate the rate.
        const payingNights = soldNights - otaNights;
        const avgRate = payingNights ? revenue / payingNights : 0;
        const otaNote = otaNights ? ` · incl. ${otaNights} OTA night${otaNights === 1 ? '' : 's'} (no price)` : '';
        const cottages = insProp ? 1 : chbFleetKeys().length || 1;
        const periodDays = dnights(pStart, pEnd) + 1;
        const endPlus = isoD(new Date(new Date(pEnd + 'T00:00:00').getTime() + 86400000));
        let occNights = 0;
        stays.forEach((x) => { if (x.b.checkIn && x.b.checkOut) { const inN = x.b.checkIn > pStart ? x.b.checkIn : pStart; const outN = x.b.checkOut < endPlus ? x.b.checkOut : endPlus; const n = dnights(inN, outN); if (n > 0) occNights += n; } });
        const occPct = Math.round((100 * occNights) / (cottages * periodDays));
        const byC = {};
        const byCn = {};
        stays.forEach((x) => { byC[x.pk] = (byC[x.pk] || 0) + total(x.b); byCn[x.pk] = (byCn[x.pk] || 0) + nights(x); });
        const ranked = Object.keys(byC).map((k) => ({ k, v: byC[k] })).sort((a, b) => b.v - a.v);
        const rankedN = Object.keys(byCn).map((k) => ({ k, n: byCn[k], v: byC[k] || 0 })).sort((a, b) => b.n - a.n);
        const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);
        if (/which (cottage|property|house).{0,24}(earn|make|most|best|top|perform|money|revenue|income|profit|lucrative)|(top|best|highest.?earning|most profitable|strongest) (cottage|property|house)|earns? (the )?most|most (money|revenue|income)/.test(q) && ranked.length) {
            const head = { type: 'figure', id: 'ins', label: `${propName(ranked[0].k)}’s your top earner — ${gbp(ranked[0].v)}`, sub: `Ahead of the rest ${plabel} · ${gbp(revenue)} across all cottages`, run: openMoney };
            return [head].concat(ranked.map((r) => ({ type: 'answer', id: 'ins-' + r.k, label: `${propName(r.k)} · ${gbp(r.v)}`, sub: `${Math.round((100 * r.v) / (revenue || 1))}% of revenue ${plabel}`, run: openMoney })));
        }
        if (/occupanc|occupied|how (full|busy)|fill rate/.test(q)) {
            return [{ type: 'figure', id: 'ins', label: `${occPct}% occupancy ${plabel}`, sub: `${occNights} of ${cottages * periodDays} cottage-nights${otaNote}`, run: openMoney }];
        }
        // Its bare "how many nights" also reads "how many nights do guests stay",
        // which is a length-of-stay question — decline those so the average family
        // below takes them (it is checked after this one).
        if (!CHB_STAYLEN_Q.test(q) && /nights? (booked|sold)|how many nights/.test(q)) {
            return [{ type: 'figure', id: 'ins', label: `${soldNights} night${soldNights === 1 ? '' : 's'} booked ${plabel}`, sub: `${occPct}% occupancy · ${gbp(revenue)} revenue${otaNote}`, run: openMoney }];
        }
        // Average LENGTH of stay — a habitual question ("how long do guests stay")
        // reads as all-year, so an unqualified ask widens to the current year; an
        // explicit period ("average stay in august") keeps it. Checked before the
        // average-RATE family so "avg stay" can't be misread as a price question.
        // CHB_STAYLEN_Q is shared with the singular "the guest" composer's veto —
        // one definition, so the two can never disagree about what is habitual.
        if (CHB_STAYLEN_Q.test(q)) {
            const hasP = !!nm || /this year|last year|last month|next month|this month/.test(q);
            const yr2 = /last year/.test(q) ? dd0.getFullYear() - 1 : dd0.getFullYear();
            const pool2 = hasP ? stays : allStays.filter((x) => x.b.checkIn && +x.b.checkIn.slice(0, 4) === yr2);
            const lbl2 = hasP ? plabel : `in ${yr2}`;
            const withN = pool2.map((x) => nights(x)).filter((n) => n > 0);
            if (!withN.length) return [{ type: 'figure', id: 'ins', label: `No stays ${lbl2} yet`, sub: 'Nothing to average', run: openMoney }];
            const avgN = Math.round((withN.reduce((s, n) => s + n, 0) / withN.length) * 10) / 10;
            const minN = Math.min(...withN), maxN = Math.max(...withN);
            return [{ type: 'figure', id: 'ins', label: `${avgN}-night average stay ${lbl2}`, sub: `Across ${withN.length} stay${withN.length === 1 ? '' : 's'} · shortest ${minN}, longest ${maxN}`, run: openMoney }];
        }
        if (/average (rate|price|nightly)|\bavg\b|\badr\b/.test(q)) {
            return [{ type: 'figure', id: 'ins', label: `${gbp(avgRate)} avg/night ${plabel}`, sub: `${gbp(revenue)} over ${payingNights} paid night${payingNights === 1 ? '' : 's'}${otaNote}`, run: openMoney }];
        }
        // Default headline. An explicit MONEY question ("revenue / income / how
        // much did I make") leads with the figure; a generic business summary
        // ("how's business", "performance") leads with NIGHTS BOOKED — money taken
        // hides the Airbnb / Vrbo stays that carry no price. Either way the OTA note
        // flags that revenue excludes those nights.
        const moneyLed = /\brevenue\b|\bincome\b|\bearn|\btakings?\b|\bturnover\b|\bgross\b|how much|top.?line/.test(q);
        if (moneyLed) {
            const head = { type: 'figure', id: 'ins', label: `${gbp(revenue)} booked ${plabel}`, sub: `${soldNights} night${soldNights === 1 ? '' : 's'} · ${occPct}% occupancy${avgRate ? ' · avg ' + gbp(avgRate) + '/night' : ''}${otaNote}`, run: openMoney, chips: [{ label: 'Last month', q: 'revenue last month' }, { label: 'This year', q: 'revenue this year' }, { label: 'Busiest month', q: 'busiest month' }, { label: 'Top cottage', q: 'which cottage earns most' }] };
            return [head].concat(ranked.filter((r) => r.v > 0).map((r) => ({ type: 'answer', id: 'ins-' + r.k, label: `${propName(r.k)} · ${gbp(r.v)}`, sub: `${Math.round((100 * r.v) / (revenue || 1))}% of revenue`, run: openMoney })));
        }
        const head = { type: 'figure', id: 'ins', label: `${soldNights} night${soldNights === 1 ? '' : 's'} booked ${plabel}`, sub: `${occPct}% occupancy · ${gbp(revenue)} revenue${avgRate ? ' · avg ' + gbp(avgRate) + '/night' : ''}${otaNote}`, run: openMoney, chips: [{ label: 'Last month', q: 'nights booked last month' }, { label: 'This year', q: 'nights booked this year' }, { label: 'Busiest month', q: 'busiest month' }, { label: 'Top cottage', q: 'which cottage earns most' }] };
        // A GENERIC "how's business / how am I doing / performance" leads with a
        // plain-English NARRATIVE (this month vs last, trend + a nudge if it dips)
        // — the numbers still follow. An explicit metric query skips it.
        let lead = [];
        const hasPeriod = !!nm || /this year|last year|last month|next month|this month/.test(q);
        if (!hasPeriod && /how.?s business|how am i doing|how are we doing|\bperformance\b|how.?s it going|how.?s trade|state of play/.test(q)) {
            try { const p = chbBusinessPulse(); if (p) lead = [{ type: 'answer', id: 'ins-pulse', wrap: true, label: `${p.arrow} ${p.label}`, sub: p.sub, run: openMoney }]; } catch (e) {}
        }
        return lead.concat([head]).concat(rankedN.filter((r) => r.n > 0).map((r) => ({ type: 'answer', id: 'ins-' + r.k, label: `${propName(r.k)} · ${r.n} night${r.n === 1 ? '' : 's'}`, sub: `${gbp(r.v)}${r.v ? ' revenue' : ' · OTA, no price'} · ${Math.round((100 * r.n) / (soldNights || 1))}% of nights`, run: openMoney })));
    }

    // 0d) Booking reference — "CHB-000123", "#123", "booking 123" → open it.
    {
        const refM = q.match(/(?:\bchb[-\s]?|#|\bbooking\s+|\bref\s+)0*(\d{1,6})\b/i);
        if (refM) {
            const id = +refM[1];
            const found = flat.find((x) => String(x.b.id) === String(id) || String(x.b.dbId) === String(id));
            if (found) return [bk(found.pk, found.b, `CHB-${String(found.b.id).padStart(6, '0')} · ${propName(found.pk)}${found.b.checkIn ? ' · ' + fmtDate(found.b.checkIn) : ''}`)];
        }
    }
    // 0e) Amount — a bare "£440" / "440" → bookings whose total, deposit or balance matches.
    {
        const amtM = q.match(/^\s*£?\s*(\d{2,6})(?:\.\d{1,2})?\s*$/);
        if (amtM) {
            const amt = +amtM[1];
            const near = (v) => Math.abs((v || 0) - amt) < 1;
            const hits = flat.filter((x) => { const p = paymentSummary(x.pk, x.b); return near(p.total) || near(p.deposit) || near(p.balance); });
            if (hits.length) {
                const head = ans(`${hits.length} booking${hits.length === 1 ? '' : 's'} near ${gbp(amt)}`, 'Matched by total, deposit or balance', () => { closeCmdK(); openBookings(); });
                return [head].concat(hits.slice(0, 10).map((x) => { const p = paymentSummary(x.pk, x.b); const which = near(p.total) ? 'total' : near(p.deposit) ? 'deposit paid' : 'balance due'; return bk(x.pk, x.b, `${gbp(amt)} ${which} · ${propName(x.pk)}`); }));
            }
        }
    }
    // 0f) Damage deposits to return — still HELD, and the guest has checked out.
    if (/deposit/.test(q) && /return|give back|owed back|hand back|refund|\bback\b/.test(q)) {
        // hasCheckedOut (time-aware) — from midnight on checkout day the guest is
        // still in until the checkout time; the WHEN answer already says so.
        // damageHeld, not hold_status: a cash-taken deposit is held too (see chbDuties).
        const rows = flat.filter((x) => damageHeld(x.pk, x.b).held > 0.005 && hasCheckedOut(x.b)).sort(byOut);
        const n = rows.length;
        const lead = n ? chbSayFirst(rows[0].b.name) : '';
        const dHead = !n ? nlgPick('dret0' + q, ['No deposits to hand back right now.', 'Nothing to refund at the moment.'])
            : n === 1 ? nlgPick('dret1' + q, [`Just one deposit to hand back — ${lead}’s.`, `${lead}’s deposit is the only one to return.`, `One to refund: ${lead}’s damages deposit.`])
                : nlgPick('dretN' + q, [`${n} deposits to hand back — ${lead} and ${chbSayN(n - 1)} other${n - 1 === 1 ? '' : 's'}.`, `${n} damages deposits waiting to go back.`]);
        const head = ans(dHead, n ? 'They’ve checked out — refund the damages deposit' : 'Nothing waiting', () => { closeCmdK(); openBookings(); });
        return [head].concat(rows.map((x) => bk(x.pk, x.b, `Checked out ${fmtDate(x.b.checkOut)} · ${propName(x.pk)}`)));
    }
    // 0g) Balances to chase — unpaid, arriving within three weeks or already overdue.
    if (/overdue|to chase|\bchase\b|chasing|behind|due soon|balances? (due|to chase|overdue|outstanding)|payments? (due|overdue)/.test(q)) {
        const rows = flat
            .map((x) => ({ x, ps: bookingDue(x.pk, x.b) }))
            .filter((r) => !r.ps.fullyPaid && r.ps.balance > 0.5)
            .map((r) => ({ ...r, days: Math.round((new Date((r.x.b.checkIn || today) + 'T00:00:00') - new Date(today + 'T00:00:00')) / 86400000) }))
            .filter((r) => r.days <= 21)
            .sort((a, b) => a.days - b.days);
        const totalDue = rows.reduce((s, r) => s + r.ps.balance, 0);
        const head = ans(
            rows.length ? `${rows.length} balance${rows.length === 1 ? '' : 's'} to chase · ${gbp(totalDue)}` : 'Nothing to chase',
            rows.length ? 'Due soon or overdue — open Bookings ▸ Needs payment' : 'All balances are in hand',
            () => { closeCmdK(); Promise.resolve(openBookings()).then(() => bookingsSetFilter('needspay')); },
        );
        return [head].concat(rows.slice(0, 12).map((r) => { const when = r.days < 0 ? `overdue — was due ${fmtDate(r.x.b.checkIn)}` : r.days === 0 ? 'arrives today' : r.days === 1 ? 'arrives tomorrow' : `arrives in ${r.days} days`; return bk(r.x.pk, r.x.b, `${gbp(r.ps.balance)} · ${when} · ${propName(r.x.pk)}`); }));
    }
    // 0h) Volume — "how many guests / bookings this year".
    if (/(how many|number of) (guests|people|bookings|stays)|guests? (this|last) year|bookings? (this|last) year/.test(q) && /year|so far|to date|202\d/.test(q)) {
        const yr = /last year/.test(q) ? +today.slice(0, 4) - 1 : +today.slice(0, 4);
        const rows = flat.filter((x) => x.b.checkIn && +x.b.checkIn.slice(0, 4) === yr);
        const heads = rows.reduce((s, x) => s + (Number(x.b.adults) || 0) + (Number(x.b.children) || 0), 0);
        const wantsBookings = /booking|stay/.test(q);
        const label = wantsBookings || heads <= 0 ? `${rows.length} booking${rows.length === 1 ? '' : 's'} in ${yr}` : `${heads} guest${heads === 1 ? '' : 's'} across ${rows.length} booking${rows.length === 1 ? '' : 's'} in ${yr}`;
        return [ans(label, `Check-ins during ${yr}`, () => { closeCmdK(); openBookings(); })];
    }

    // 0h3) Entity-composed bookings filter — any query carrying a date window
    // and/or a money bound (chbEntities) plus a bookings-ish word composes here:
    // "bookings at jollyboat in august", "stays next month over £500", "guests
    // this weekend", "bookings over £600". One branch instead of a regex per
    // combination; the specialist branches above (insights, volume, chase) keep
    // their richer answers because they run first.
    {
        const ents = CHB_SEARCH.understand(q).entities || {};
        // Source qualifier: "airbnb booking", "any vrbo stays", "direct bookings".
        // OTA channels come from imported blocks (isOtaBlock); "direct" = our own
        // bookings. A qualifier alone (no date/amount) is enough to compose here.
        const SRC = /\bairbnb\b/.test(q) ? 'airbnb' : /\bvrbo\b|\bhomeaway\b/.test(q) ? 'vrbo' : /\bbooking\.?com\b/.test(q) ? 'bookingcom' : /\b(ota|channel|platform|external)\b/.test(q) ? 'ota' : /\b(direct|website|own site|my site)\b/.test(q) ? 'direct' : null;
        if ((ents.dateRange || ents.amount || SRC) && /\bbook(ing|ings|ed)?\b|\bstays?\b|\bguests?\b|\bwho\b/.test(q) && !/\barriv|\bleav|check.?(in|out)|\bstaying\b/.test(q)) {
            const dr = ents.dateRange;
            const within = (ci, co) => !dr || (ci && (co || ci) > dr.from && ci <= dr.to); // stay overlaps the window
            const amtOk = (t) => {
                if (!ents.amount) return true;
                const { op, value } = ents.amount;
                return op === 'over' ? t > value : op === 'under' ? t < value : Math.abs(t - value) <= 25;
            };
            const wantOta = SRC && SRC !== 'direct'; // asked for a specific/any OTA channel
            const OTA_LABEL = { airbnb: 'Airbnb', vrbo: 'Vrbo', bookingcom: 'Booking.com' };
            const srcMatch = (s) => !SRC || SRC === 'ota' || s === SRC; // null/"ota" → any OTA; else the exact channel
            // Direct bookings — dropped when the query asks specifically for OTA.
            let rows = wantOta ? [] : flat.filter((x) => (!ents.prop || x.pk === ents.prop) && within(x.b.checkIn, x.b.checkOut));
            rows = rows.map((x) => ({ ...x, _t: paymentSummary(x.pk, x.b).total })).filter((x) => amtOk(x._t)).sort(byIn);
            // OTA blocks only — the owner's maintenance blocks are NOT bookings
            // ("blocked out dates aren't booking days"). Dropped for "direct" and
            // for amount filters (OTA blocks carry no price).
            const eRows = (SRC === 'direct' || ents.amount) ? [] : blocks.filter((x) => isOtaBlock(x.bl) && srcMatch(x.bl.source) && (!ents.prop || x.pk === ents.prop) && within(x.bl.checkIn, x.bl.checkOut)).sort(byBlkIn);
            const srcBit = SRC ? (SRC === 'direct' ? 'direct ' : (OTA_LABEL[SRC] || 'OTA') + ' ') : '';
            const bits = [ents.prop ? `at ${propName(ents.prop)}` : '', dr ? dr.label : '', ents.amount ? `${ents.amount.op} ${gbp(ents.amount.value)}` : ''].filter(Boolean).join(' · ');
            const n = rows.length + eRows.length;
            const sum = rows.reduce((s, x) => s + x._t, 0);
            const head = ans(
                n ? `${n} ${srcBit}booking${n === 1 ? '' : 's'}${bits ? ' — ' + bits : ''}` : `No ${srcBit}bookings${bits ? ' ' + bits : ''}`,
                n ? (sum ? `${gbp(sum)} across them` : (wantOta ? 'Imported from the channel calendar' : 'Matching stays')) : 'Nothing in that window',
                () => { closeCmdK(); openBookings(); },
                dr ? [calChip(dr.from)] : null,
            );
            return [head]
                .concat(rows.slice(0, 10).map((x) => bk(x.pk, x.b, `${fmtDate(x.b.checkIn)}–${fmtDate(x.b.checkOut)} · ${gbp(x._t)} · ${propName(x.pk)}`)))
                .concat(eRows.slice(0, 6).map((x) => ext(x.pk, x.bl, `${fmtDate(x.bl.checkIn)}–${fmtDate(x.bl.checkOut)} · ${propName(x.pk)}`)));
        }
    }
    // 0h2) Cottage dossier — a cottage name alone (or "…settings/setup/manage")
    // returns a CARD: live facts up top, then every editing path for that cottage.
    // This is what lets a cottage's whole settings index live inside search.
    {
        const keys = Object.keys(propertyMeta || {});
        const bare = q.trim().replace(/^(the )\s*/, '').replace(/\s+(settings?|set ?up|manage|options?|everything|all|details?|admin|page|info)$/, '').trim();
        const dPk = keys.find((k) => bare === k.toLowerCase() || bare === ((propertyMeta[k].name || '').toLowerCase()));
        if (dPk && typeof ACCOM_SECTIONS !== 'undefined' && typeof settingsOpenAccomSec === 'function') {
            const cName = propName(dPk);
            const bs = (dbBookings[dPk] || []).filter((b) => b.checkIn);
            const inRes = bs.find((b) => isInResidence(b)); // in residence NOW (time-aware)
            const next = bs.filter((b) => b.checkIn > today).sort((a, b) => (a.checkIn < b.checkIn ? -1 : 1))[0];
            const yr = +today.slice(0, 4);
            const rev = bs.filter((b) => +b.checkIn.slice(0, 4) === yr).reduce((s, b) => s + ((b.agreedPrice && b.agreedPrice.total) || 0), 0);
            const facts = [
                inRes ? `${inRes.name || 'Guest'} here until ${fmtDate(inRes.checkOut)}` : next ? `Next in ${fmtDate(next.checkIn)}` : 'Nothing upcoming',
                inRes && next ? `next in ${fmtDate(next.checkIn)}` : null,
                rev ? `${gbp(rev)} booked in ${yr}` : null,
            ].filter(Boolean).join(' · ');
            const openSec = (sec) => () => cmdkOpenAccomSec(dPk, sec);
            const runQ = (query) => () => { const el = document.getElementById('cmdk-input'); if (el) el.value = query; cmdkSearch(query); };
            const head = ans(cName, facts, openSec('rates'), [{ label: 'Bookings', run: runQ(cName + ' bookings') }].concat(next ? [calChip(next.checkIn)] : []));
            const rows = ACCOM_SECTIONS.map((s) => ({ type: 'action', id: 'dsr-' + dPk + '-' + s.id, label: s.label.replace(/&amp;/g, '&'), sub: (s.sub || '').replace(/&amp;/g, '&'), run: openSec(s.id) }));
            return [head].concat(rows);
        }
    }

    // 0i) Cottage pivot — "Jollyboat bookings", "bookings at 21a", "who's at
    // Pimpernel" — this cottage's stays. Needs an EXPLICIT cottage name (not the
    // single-cottage fallback) so it can't swallow "upcoming bookings". A guest
    // who is IN RESIDENCE (checked in, not yet out) ALWAYS leads — "who's at
    // Jollyboat" must answer with the person there NOW, never "Nothing upcoming"
    // while someone's mid-stay.
    {
        const keys = Object.keys(propertyMeta || {});
        const namedPk = keys.find((k) => q.includes(k.toLowerCase()) || ((propertyMeta[k].name || '').toLowerCase() && q.includes((propertyMeta[k].name || '').toLowerCase())));
        if (namedPk && /\bbookings?\b|\bstays?\b|\bcalendar\b|who.?s (at|in|staying)|who is (at|in|staying)|anyone (at|in|staying)|staying (at|in)\b|\bcurrently\b/.test(q)) {
            const cName = propName(namedPk);
            const all = flat.filter((x) => x.pk === namedPk && x.b.checkIn);
            const inHouse = all.filter((x) => isInResidence(x.b)).sort(byIn);
            const upcoming = all.filter((x) => x.b.checkIn > today).sort(byIn);
            const nowAsk = /who.?s (at|in|staying)|who is (at|in|staying)|anyone (at|in|staying)|staying (at|in)\b|\bcurrently\b|\bright now\b/.test(q);
            const now = inHouse[0];
            const head = ans(
                now
                    ? `${now.b.name || 'A guest'} is at ${cName} until ${fmtDate(now.b.checkOut)}`
                    : upcoming.length
                        ? (nowAsk ? `Nobody's at ${cName} right now — ${upcoming.length} upcoming` : `${upcoming.length} upcoming at ${cName}`)
                        : (nowAsk ? `Nobody's at ${cName} right now` : `Nothing upcoming at ${cName}`),
                now ? (upcoming.length ? `In residence now · ${upcoming.length} upcoming after` : 'In residence now') : 'Bookings for this cottage',
                () => { closeCmdK(); openBookings(); },
                [calChip(now ? now.b.checkIn : upcoming[0] ? upcoming[0].b.checkIn : today)],
            );
            const rows = inHouse.concat(upcoming);
            return [head].concat(rows.slice(0, 10).map((x) => bk(x.pk, x.b, (x.b.checkIn <= today && (x.b.checkOut || '') > today ? 'In residence · until ' + fmtDate(x.b.checkOut) : `${fmtDate(x.b.checkIn)}–${fmtDate(x.b.checkOut)}`))));
        }
    }

    // 0j) Topic dossiers — a bare topic word returns that topic's whole page
    // inside search: live facts + every path. Money / Status / Messages.
    const runQ = (query) => () => { const el = document.getElementById('cmdk-input'); if (el) el.value = query; cmdkSearch(query); };
    const toMng = (sec) => () => { closeCmdK(); Promise.resolve(openArea()).then(() => settingsOpen(sec)); };
    const A = (id, label, sub, run) => ({ type: 'action', id, label, sub, run });
    if (/^\s*(the\s+)?(money|payments?|takings|finances?|accounts?|cash)\s*(overview|summary|dashboard)?\s*$/.test(q)) {
        let outstanding = 0, owers = 0, held = 0, depN = 0;
        flat.forEach((x) => {
            const ps = bookingDue(x.pk, x.b);
            if (!ps.fullyPaid && ps.balance > 0.5) { outstanding += ps.balance; owers++; }
            // Same as the brief: swallowing here silently under-reports how much
            // deposit money is being held.
            try { const dh = damageHeld(x.pk, x.b); if (dh && dh.held > 0.5) { held += dh.held; depN++; } } catch (e) { chbSwallow(e, 'money-held'); }
        });
        const facts = [outstanding > 0.5 ? `${gbp(outstanding)} to collect` : 'All balances in', held > 0.5 ? `${gbp(held)} deposits to return` : null].filter(Boolean).join(' · ');
        const head = ans('Payments', facts, () => { closeCmdK(); openAccounts(); });
        return [head].concat([
            A('mdsr-open', 'Open Payments', 'Money & reconciliation', () => { closeCmdK(); openAccounts(); }),
            owers ? A('mdsr-owe', `Who owes money · ${owers}`, `${gbp(outstanding)} outstanding`, runQ('who owes me money')) : null,
            depN ? A('mdsr-dep', 'Deposits to return', `${gbp(held)} to hand back`, runQ('deposits to return')) : null,
            A('mdsr-rev', 'Revenue this month', 'Booked income', runQ('revenue this month')),
            A('mdsr-set', 'Payment settings', 'Square & deposit policy', toMng('payments')),
        ].filter(Boolean));
    }
    if (/^\s*(the\s+)?(status|system status|health|health check|site status|system check|how.?s (the )?(site|system|business))\s*$/.test(q)) {
        const ny = (() => { try { return needsYouItems().length; } catch (e) { return 0; } })();
        const autoOk = typeof __nyCronQuiet === 'undefined' ? true : !__nyCronQuiet;
        const head = {
            type: autoOk ? 'answer' : 'figure', id: 'sdsr',
            label: autoOk && !ny ? 'All systems operational' : 'System status',
            sub: `${autoOk ? 'Automation running' : 'Automation looks stopped'} · ${ny ? ny + ' thing' + (ny === 1 ? '' : 's') + ' need you' : 'nothing needs you'}`,
            run: toMng('diagnostics'),
        };
        return [head].concat([
            A('sdsr-open', 'Open Status', 'Health, insights & updates', toMng('diagnostics')),
            ny ? A('sdsr-ny', `${ny} thing${ny === 1 ? '' : 's'} need you`, 'The Today needs-you strip', () => { closeCmdK(); tryAccessBackOffice(); }) : null,
            A('sdsr-act', 'Activity log', 'Every change & action', () => { closeCmdK(); nav('view-activity-log'); }),
            A('sdsr-bak', 'Back up your data', 'Download a database backup', toMng('diagnostics')),
        ].filter(Boolean));
    }
    if (/^\s*(the\s+)?(messages?|chats?|guest (chat|message)s?|inbox chats?)\s*$/.test(q)) {
        const n = typeof __nyChats === 'number' ? __nyChats : 0;
        const head = ans('Messages', n ? `${n} chat${n === 1 ? '' : 's'} waiting a reply` : 'Guest chats', () => { closeCmdK(); Promise.resolve(openInbox()).then(() => inboxFolder('messages')); });
        return [head].concat([
            A('gdsr-open', 'Open Messages', 'Guest chat folder', () => { closeCmdK(); Promise.resolve(openInbox()).then(() => inboxFolder('messages')); }),
            A('gdsr-away', 'Away auto-reply', 'Out-of-hours acknowledgement', toMng('chat-away')),
            A('gdsr-ans', 'Instant chat answers', 'Auto-answers to chat chips', toMng('chat-answers')),
        ]);
    }

    // 0k) Needs-you — pull the prioritised to-do list into the palette so it's
    //     actionable from any screen ("what needs me", "to-do", "my tasks").
    if (/\bneeds? (me|you|doing|action|attention)|to.?do list|to.?do\b|my (tasks?|jobs?)|what.*(should i do|needs doing|to action|to sort)|priorit|action list|jobs? to do\b/.test(q)) {
        const plain = (s) => String(s || '').replace(/<[^>]+>/g, '').replace(/&rsquo;/g, '’').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#39;/g, "'");
        let ny = [];
        try { ny = needsYouItems(); } catch (e) {}
        const head = ans(ny.length ? `${ny.length} thing${ny.length === 1 ? '' : 's'} need you` : 'Nothing needs you — all clear', ny.length ? 'Your prioritised to-do list' : 'You’re all caught up', () => { closeCmdK(); if (typeof nav === 'function') nav('view-backoffice'); });
        return [head].concat(ny.slice(0, 10).map((it, i) => ({
            type: 'answer', id: 'ny-' + i, label: plain(it.label), sub: plain(it.sub),
            run: typeof it.run === 'function' ? it.run : () => { closeCmdK(); if (typeof nav === 'function') nav('view-backoffice'); },
        })));
    }
    // 0l) Availability gaps — multi-night open windows over the next 60 days, per
    //     cottage ("gaps", "when is Jollyboat free", "availability next month").
    //     Plain "free tonight" still falls through to branch 8 below.
    if (/\bgaps?\b/.test(q) || (/\b(free|availab|vacan|open|empty|spare)\b/.test(q) && /\b(month|week|weekend|coming|soon|next|window|when|august|september|october|november|december|january|february|march|april|june|july)\b/.test(q))) {
        const gpk = typeof cmdkCottageFor === 'function' ? cmdkCottageFor(q) : null;
        const gd = dpParse(today); const ge = new Date(gd.getFullYear(), gd.getMonth(), gd.getDate() + 60);
        const gTo = formatDashed(ge);
        const gaps = (typeof todayGaps === 'function' ? todayGaps(today, gTo, gpk) : []).sort((a, b) => a.from.localeCompare(b.from)).slice(0, 10);
        const scope = gpk && propertyMeta[gpk] ? propertyMeta[gpk].name : 'all cottages';
        const gHead = ans(gaps.length ? `${gaps.length} open window${gaps.length === 1 ? '' : 's'} · ${scope}` : `No gaps at ${scope} in the next 60 days`, gaps.length ? 'Next 60 days · tap one to see it on the calendar' : 'Fully booked', () => { closeCmdK(); if (typeof nav === 'function') nav('view-backoffice'); });
        return [gHead].concat(gaps.map((g) => ({
            type: 'answer', id: 'gap-' + g.propKey + '-' + g.from,
            label: `${g.name} free ${fmtDate(g.from)} → ${fmtDate(g.to)}`,
            sub: `${g.nights} night${g.nights === 1 ? '' : 's'} open`,
            run: () => cmdkJumpTimeline(g.from),
            chips: [{ label: 'Show on calendar', run: () => cmdkJumpTimeline(g.from) }, { label: 'Add booking', run: () => { closeCmdK(); if (typeof tlAddAt === 'function') tlAddAt(g.propKey, g.from); } }],
        })));
    }
    // 0m) Jump the timeline to a month — "jump to August", "go to next month".
    {
        const jm = q.match(/\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\b/);
        if (/\b(jump|scroll|go to|take me|show me the|open the)\b/.test(q) && (jm || /\bnext month|this month|the (calendar|timeline)\b/.test(q))) {
            const mm = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
            const now = dpParse(today);
            let target;
            if (jm) {
                const mi = mm.indexOf(jm[1].slice(0, 3));
                let y = now.getFullYear();
                if (mi < now.getMonth()) y++; // a month already gone this year → next year
                target = formatDashed(new Date(y, mi, 1));
            } else if (/next month/.test(q)) {
                target = formatDashed(new Date(now.getFullYear(), now.getMonth() + 1, 1));
            } else {
                target = formatDashed(new Date(now.getFullYear(), now.getMonth(), 1));
            }
            return [ans('Jump the calendar to ' + fmtDate(target), 'Scrolls the Today timeline there', () => cmdkJumpTimeline(target))];
        }
    }

    // 0n) Search dead ends — the review-and-teach surface for queries that found
    // nothing (chbMissRecord). Each row retries its query; its chips teach the
    // model what the phrasing MEANT (chbNluLearn → synced) or forget the entry.
    if (/^(search )?dead.?ends?$|^search misses$|^teach (the )?(assistant|search|model)\b|what (couldn.?t|didn.?t) (you|search) (answer|find)/.test(q)) {
        const list = chbMissList().slice().reverse();
        const head = ans(
            list.length ? `${list.length} search${list.length === 1 ? '' : 'es'} found nothing` : 'No dead ends — recent searches all found something',
            list.length ? 'Tap one to retry it, or teach the assistant what it meant' : 'Searches that find nothing are remembered here so you can teach the assistant',
            null,
        );
        return [head].concat(list.slice(0, 8).map((m) => {
            let sugg = [];
            try { sugg = chbNluSuggestSmart(m.t) || []; } catch (e) {}
            return {
                type: 'answer', id: 'miss-' + chbNluHashStr(m.t),
                label: `“${m.t}”`,
                sub: `Searched ${m.n > 1 ? m.n + ' times' : 'once'} · nothing found`,
                run: () => { const el = document.getElementById('cmdk-input'); if (el) el.value = m.t; cmdkSearchCore(m.t, true); },
                chips: sugg.slice(0, 2).map((c) => ({
                    label: `Teach: means “${c}”`,
                    run: () => { chbNluLearn(m.t, c); chbMissForget(m.t); const el = document.getElementById('cmdk-input'); if (el) el.value = c; cmdkSearchCore(c, true); },
                })).concat([{ label: 'Forget this', run: () => { chbMissForget(m.t); cmdkSearchCore('search dead ends', false); } }]),
            };
        }));
    }
    // 1) Payments — who owes, who's paid in full, who's paid a deposit.
    if (/\bowe|owes|owing|owed|balance|outstanding|unpaid|to collect|to chase|money|paid|payment|deposit|paying|settle/.test(q)) {
        const withPs = flat.map((x) => ({ ...x, ps: paymentSummary(x.pk, x.b) }));
        const negative = /haven.?t|hasn.?t|not paid|n.t paid|still|owe|outstanding|unpaid|to (pay|collect|chase)|chase|behind/.test(q);
        // "who's paid a deposit" — something down (whether or not fully paid).
        if (/deposit/.test(q) && !negative) {
            const rows = withPs.filter((x) => x.ps.deposit > 0.5).sort(byIn);
            const n = rows.length;
            const dHead = !n ? nlgPick('dep0' + q, ['No deposits down yet.', 'Nobody’s put a deposit down so far.'])
                : nlgPick('depN' + q, [`${n} guest${n === 1 ? ' has' : 's have'} a deposit down.`, `${n} guest${n === 1 ? '' : 's'} paid a deposit so far.`]);
            const head = ans(dHead, n ? 'Deposits received — tap to see them' : 'Nothing taken', () => { closeCmdK(); openBookings(); });
            // The QUESTION is rental, so the leading figure stays ps.deposit — but
            // the trailing "£X due" answers a different one and takes the due frame.
            return [head].concat(rows.map((x) => {
                const d = moneyState(x.pk, x.b);
                const done = d.gt.fullyPaid || d.gt.balance <= 0.5;
                return bk(x.pk, x.b, `${gbp(x.ps.deposit)} paid${done ? ' · in full' : ' · ' + gbp(d.gt.balance) + ' due'} · ${propName(x.pk)}`);
            }));
        }
        // "who's paid / paid in full / settled" — fully-paid bookings.
        if ((/\bpaid\b|paid in full|fully paid|settled|paid up/.test(q)) && !negative) {
            const rows = withPs.filter((x) => x.ps.fullyPaid && x.ps.total > 0).sort(byIn);
            const n = rows.length;
            const pHead = !n ? nlgPick('paid0' + q, ['Nobody’s paid in full yet.', 'No one settled up so far.'])
                : nlgPick('paidN' + q, [`${n} guest${n === 1 ? '' : 's'} all squared up in full.`, `${n === 1 ? 'One booking' : n + ' bookings'} paid in full.`, `${n} guest${n === 1 ? ' is' : 's are'} fully settled.`]);
            const head = ans(pHead, n ? 'Settled bookings' : 'Nothing settled yet', () => { closeCmdK(); openBookings(); });
            return [head].concat(rows.map((x) => bk(x.pk, x.b, `Paid ${gbp(x.ps.total)} · ${propName(x.pk)}${x.b.checkIn ? ' · ' + fmtDate(x.b.checkIn) : ''}`)));
        }
        // Default (owes / hasn't paid in full) — outstanding balances, led by the total
        // and the biggest single ower so the answer reads like a person, not a table.
        // Deposit-aware, because "who owes me" means what is still to come IN.
        // The sibling branches above stay on the rental summary on purpose.
        const rows = withPs
            .map((x) => ({ ...x, ps: bookingDue(x.pk, x.b) }))
            .filter((x) => !x.ps.fullyPaid && x.ps.balance > 0.5)
            .sort(byIn);
        const total = rows.reduce((s, x) => s + x.ps.balance, 0);
        const n = rows.length;
        const big = rows.slice().sort((a, b) => b.ps.balance - a.ps.balance)[0];
        const lead = big ? chbSayFirst(big.b.name) : '';
        const owedHead = !n
            ? nlgPick('owed0' + q, ['You’re all square — nothing to collect.', 'Everyone’s paid up.', 'Nothing outstanding — all settled up.'])
            : n === 1
                ? nlgPick('owed1' + q, [`${gbp(total)} to collect — all from ${lead}.`, `Just ${lead} to chase, for ${gbp(total)}.`, `${lead} owes you ${gbp(total)} — the only one outstanding.`])
                : nlgPick('owedN' + q, [
                    `${gbp(total)} to collect from ${n} guests — ${lead}’s the biggest at ${gbp(big.ps.balance)}.`,
                    `You’re owed ${gbp(total)} across ${n} guests, ${lead} leading at ${gbp(big.ps.balance)}.`,
                    `Looks like ${gbp(total)} still to come in — ${lead}’s the big one (${gbp(big.ps.balance)}), then ${chbSayN(n - 1)} more.`,
                ]);
        // …AND THE SUB MUST NOT PROMISE A LIST THAT OMITS WHO THE SENTENCE NAMED.
        // This answer counts owner-arranged money by design ("records and direct
        // answers keep the full state"), while Bookings ▸ Needs payment excludes
        // it by design — so the owner read a total, tapped through, and met a list
        // missing the guest just called the biggest. Both rules stay; the sub now
        // says how much of the figure is settled by hand, so the shorter list is
        // expected rather than a contradiction.
        const arranged = rows.filter((x) => bookingOwnerArranged(x.b));
        const armTotal = arranged.reduce((s, x) => s + Math.max(0, x.ps.balance || 0), 0);
        const head = ans(
            owedHead,
            n
                ? (armTotal > 0.005
                    ? `${gbp(armTotal)} of it you settle yourself · tap for the rest — Bookings ▸ Needs payment`
                    : 'Tap to chase them — Bookings ▸ Needs payment')
                : 'No balances outstanding',
            () => { closeCmdK(); Promise.resolve(openBookings()).then(() => bookingsSetFilter('needspay')); },
            n ? [{ label: 'Overdue only', q: 'overdue balances' }, { label: 'Deposits to return', q: 'deposits to return' }, { label: 'Who’s paid in full', q: 'who has paid in full' }] : null,
        );
        // BULK: the answer already holds the set, so chasing every balance is one tap
        // on the answer itself rather than one journey per guest. Null under two owers.
        const bulk = chbBulkBalanceAction(rows);
        if (bulk) head.actions = [bulk];
        return [head].concat(rows.map((x) => {
            const r = bk(x.pk, x.b, `${gbp(x.ps.balance)} still due · ${propName(x.pk)}${x.b.checkOut ? ' · out ' + fmtDate(x.b.checkOut) : ''}`);
            // Due NOW = finished stay or inside the window — the hub's own
            // derivation, so the capsule and the payask cannot disagree.
            try { r.stcap = hasCheckedOut(x.b) || bookingInBalanceWindow(x.b) ? { tone: 'warn', text: 'Due now' } : { tone: 'unk', text: 'Not due yet' }; } catch (e) {}
            return r;
        }));
    }
    // 2) Leaving / checking out (today, or this week) — direct bookings AND OTA blocks.
    if (/\bleav|leaving|check.?out|checking out|departing|departure|checkout\b/.test(q)) {
        const rows = flat.filter((x) => x.b.checkOut && x.b.checkOut >= rStart && x.b.checkOut <= rEnd).sort(byOut);
        const eRows = blocks.filter((x) => x.bl.checkOut && x.bl.checkOut >= rStart && x.bl.checkOut <= rEnd).sort(byBlkOut);
        const n = rows.length + eRows.length;
        const lead = n ? chbSayFirst((rows[0] && rows[0].b.name) || (eRows[0] && otaName(eRows[0].bl.source) + ' guest') || '') : '';
        const lHead = !n ? nlgPick('leave0' + q, [`Nobody heading off ${when}.`, `No check-outs ${when} — a calm one.`])
            : n === 1 ? nlgPick('leave1' + q, [`Just one checkout ${when} — ${lead} heads off.`, `${lead}’s your only departure ${when}.`, `One heading home ${when}: ${lead}.`])
                : nlgPick('leaveN' + q, [`${n} checking out ${when} — ${lead} and ${chbSayN(n - 1)} more.`, `${n} guests heading off ${when}.`]);
        const head = ans(lHead, 'Departures · direct & OTA', () => { closeCmdK(); tryAccessBackOffice(); }, [{ label: 'Arriving', q: 'who’s arriving today' }, { label: 'This week', q: 'leaving this week' }, { label: 'Staying now', q: 'who’s staying now' }, calChip(rStart)]);
        return [head]
            .concat(rows.map((x) => bk(x.pk, x.b, `Checks out ${fmtDate(x.b.checkOut)}${x.b.checkOutTime ? ' · ' + x.b.checkOutTime : ''} · ${propName(x.pk)}`)))
            .concat(eRows.map((x) => ext(x.pk, x.bl, `Checks out ${fmtDate(x.bl.checkOut)} · ${propName(x.pk)}`)));
    }
    // 3) Upcoming / next bookings — future arrivals, soonest first (direct & OTA).
    // "who's staying next" reads as the NEXT arrival, not who's in-house now — so
    // "staying/stay/in next" is an upcoming cue and must beat the staying branch.
