let __hubReturnView = 'view-backoffice';

async function openBookingHub(bookingId, quiet) {
    if (!isAuthenticated) {
        tryAccessBackOffice();
        return;
    }
    let b = findBookingById(bookingId);
    // A failed RELOAD and a MISSING record are different facts: collapsing them
    // said "that booking is no longer here" about a booking that was fine, then
    // moved the owner off the page they had just tapped.
    let loadFailed = false;
    if (!b) {
        // loadData() isolates each task's failure and so never rejects — a
        // try/catch here would be dead code. It REPORTS instead.
        let r = null;
        try {
            r = await loadData();
        } catch (e) {
            loadFailed = true;
        }
        if (r && r.ok === false) loadFailed = true;
        b = findBookingById(bookingId);
    }
    if (!b) {
        if (loadFailed) {
            adminNetFail(() => window.openBookingHub(bookingId, quiet));
            return;
        }
        toast('That booking is no longer here.', 'error');
        window.openBookings();
        return;
    }
    const prev = document.querySelector('.page-view.active');
    const alreadyHere = prev && prev.id === 'view-booking-hub' && __hubBookingId === bookingId;
    if (prev && prev.id !== 'view-booking-hub') __hubReturnView = prev.id;
    __hubBookingId = bookingId;
    try { chbStampRecent('booking', bookingId, b && b.name); } catch (e) {} // cross-page memory
    const content = document.getElementById('booking-hub-content');
    if (bookingsSplitWide()) {
        // Master–detail: dock the hub beside the bookings index (the shared
        // #booking-hub-content node re-parents into the pane) — no page swap.
        const pane = document.getElementById('bookings-detail-pane');
        if (content && content.parentElement !== pane) pane.appendChild(content);
        // QUIET MEANS DON'T MOVE THE OWNER, not just don't scroll. The only quiet caller
        // is renderBookings' auto-select, which exists so Today never shows an empty
        // pane — a reason that only applies when you are ON Today. From anywhere else it
        // was dragging you to Today the moment the bookings finished loading, which
        // clobbered both a restored screen and a tapped `?open=` notification at =1200px
        // (measured: restore landed view-inbox at 260ms, this pulled it to
        // view-backoffice at 367ms). Dock silently instead.
        if (quiet && prev && prev.id !== 'view-backoffice') {
            markBookingsSelection();
            return;
        }
        if (!prev || prev.id !== 'view-backoffice') {
            nav('view-backoffice');
            adminHistPush('view-backoffice');
            try {
                renderCalendar();
            } catch (e) {}
            renderBookings(); // renders the index; the selection highlights itself
        } else {
            markBookingsSelection();
        }
        // A tap can come from the timeline at the top of the page (or from
        // Money/Inbox) — bring the docked hub into view so the action visibly
        // lands somewhere. `quiet` = the dashboard's own auto-select, which
        // must never yank the owner down the page.
        if (pane && !quiet) pane.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    } else {
        const home = document.getElementById('view-booking-hub');
        if (content && home && content.parentElement !== home) home.appendChild(content);
        nav('view-booking-hub');
        if (!alreadyHere) adminHistPush('view-booking-hub', null, { hubBooking: bookingId });
        // A hub without its record is a blank screen, so remember WHICH booking —
        // stamped after the record resolved, so a failed open never becomes the target
        // a reload lands on. The NUMERIC dbId, so the remembered target and the
        // notification URL (?open=booking-42) speak one vocabulary.
        chbNavRemember('booking-' + (b && b.dbId != null ? b.dbId : bookingId));
        window.scrollTo({ top: 0 });
        // The condensed bar names the RECORD, not the screen type: mid-scroll
        // the identity row (cottage tag + guest name) is under the fixed
        // header, so "Booking" answered the wrong question — whose page is
        // this. Standalone only — a docked pane leaves the workspace's title.
        try {
            // FIRST name only: the condensed slot is ~56px at 390px (crown
            // + five dock icons take the rest), so a full name clips to "Deb…".
            const t = document.getElementById('admin-head-title');
            const first = String(b.name || '').trim().split(/\s+/)[0];
            if (t && first) t.textContent = first;
        } catch (e) {}
    }
    renderBookingHub();

    // Async enrichments — each fills its own card when it lands (guarded so a
    // slow response never paints over a different booking's hub).
    const dbId = b.dbId;
    // ONE round trip fills the Activity feed — payments, events and logged
    // email bodies arrive together (bookings.php hub_bundle), so on a weak
    // signal the page fills in at once instead of card by card. Guarded like
    // the fetches it replaces: a slow response never paints another booking's
    // hub. The single-purpose endpoints still exist for their other callers.
    {
        apiPost('bookings.php', { action: 'hub_bundle', id: dbId })
            .then((r) => {
                const el2 = document.getElementById('hub-history');
                if (!el2 || __hubBookingId !== bookingId) return;
                el2.innerHTML = hubActivityHtml(r || {}, bookingId);
                // The disclosure groups' summary rows state their conclusion
                // from the same bundle: Activity's latest line, and the
                // Emails group's last send when nothing synchronous (the
                // pre-arrival stamp) already answered it.
                const act = document.getElementById('bhub-activity-sum');
                if (act) act.textContent = hubActivitySum(r || {});
                const em = document.getElementById('bhub-emails-sum');
                // A capsule (markup), so innerHTML — the slot is empty until filled.
                if (em && !em.textContent) em.innerHTML = hubEmailsSum(r || {});
            })
            .catch(() => {
                const el2 = document.getElementById('hub-history');
                // A dropped bundle left the card saying only that it had failed. The
                // whole hub comes from ONE round trip, so re-opening it is the retry.
                if (el2 && __hubBookingId === bookingId) el2.innerHTML = '<div class="bhub-empty">Couldn’t load the activity — the connection dropped. <button type="button" class="bhub-actlink" ' + chbAttrs('openBookingHub', bookingId) + '>Try again</button></div>';
                const act = document.getElementById('bhub-activity-sum');
                if (act && __hubBookingId === bookingId) act.textContent = 'Couldn’t load';
            });
    }
    // Guest-intel mentions ride the history corpus index: if it isn't built yet,
    // build it in the background (10-min freshness; also warms semantic search)
    // and slot the mention rows in when it lands — same guarded pattern as the
    // other async cards. If the card wasn't rendered (nothing known) but
    // mentions ARRIVE, the whole hub repaints once to add it.
    try {
        if (!CHB_HIST.built && (DARKSTAR.st || CHB_ENC.st)) {
            Promise.resolve(chbHistoryIndexBuild()).then(() => {
                if (__hubBookingId !== bookingId || !CHB_HIST.built) return;
                const fresh = findBookingById(bookingId);
                if (!fresh) return;
                const mentions = chbGuestMentions(fresh);
                if (!mentions.length) return;
                const holder = document.getElementById('hub-intel-mentions');
                if (holder) { __hubIntelMentions = mentions; holder.innerHTML = hubIntelMentionRowsHtml(mentions); }
                else renderBookingHub();
            }).catch(() => {});
        }
    } catch (e) {}
}

// The Activity group's summary line — the newest thing that happened, from
// the same bundle the feed renders (a ledger row beats an event when newer).
function hubActivitySum(r) {
    const evs = (r && r.events) || [];
    const pays = (r && r.payments) || [];
    const evTop = evs.reduce((a, x) => (!a || String(x.at || '') > String(a.at || '') ? x : a), null);
    const payTop = pays.reduce((a, x) => (!a || String(x.created_at || '') > String(a.created_at || '') ? x : a), null);
    let label = '';
    if (payTop && (!evTop || String(payTop.created_at || '') > String(evTop.at || ''))) {
        label = `${/damages_return/.test(String(payTop.kind || '')) ? 'Deposit return' : 'Payment'} · ${gbp(Math.abs(parseFloat(payTop.amount)) || 0)}`;
    } else if (evTop) {
        label = String(evTop.summary || '').split('—')[0].trim();
    }
    if (!label) return 'Nothing yet';
    return label.length > 36 ? label.slice(0, 35) + '…' : label;
}
// The Emails group's summary when the booking itself can't answer it (no
// pre-arrival stamp): the last logged send, said as its conclusion.
function hubEmailsSum(r) {
    const e = ((r && r.events) || [])
        .filter((x) => /^email\./.test(String(x.action || '')))
        .reduce((a, x) => (!a || String(x.at || '') > String(a.at || '') ? x : a), null);
    if (!e) return 'Nothing sent yet';
    return /confirmation/i.test(String(e.summary || '')) ? stCap('ok', 'Confirmation sent') : stCap('ok', 'Sent');
}
function bookingHubBack() {
    const back = __hubReturnView && document.getElementById(__hubReturnView) ? __hubReturnView : 'view-backoffice';
    if (back === 'view-accounts') {
        openAccounts();
        return;
    }
    if (back === 'view-backoffice') {
        nav('view-backoffice');
        Promise.resolve(initBackOffice()).catch(() => {});
        return;
    }
    if (back === 'view-inbox') {
        openInbox();
        return;
    }
    window.openBookings();
}

// JS mirror of pricing.php's booking_within_balance_window: a CUSTOM due date is
// INCLUSIVE (the day named is the day the full amount is asked), the STANDARD
// path strict. Deliberately two comparisons — the client must make the same two
// or the figure it SHOWS disagrees with the figure the link CHARGES.
function bookingInBalanceWindow(b) {
    const due = bookingPlanDueDate(b);
    if (!due) return false;
    const today = todayDashed();
    return b.balanceDueDate ? today >= due : today > due;
}
// The stage strip + the single next action for a booking's current state.
// THE EMAIL ASK A BOOKING IS UP TO — deposit first, then the balance once
// something is in; a finished stay only ever chases the balance. ONE definition,
// because the banner's CTA (hubPipelineHtml) and the Payments row's email button
// (renderBookingHub) both read it and the two are on screen together — derived
// separately they could ask for different stages of the same money. It mirrors
// booking_payment_kind's window clause too, because the SUM is derived from the
// stage: get it wrong and the banner over-asks outside the window and under-asks
// inside it.
// A SLICE IS NOT ITS STAGE. This read `gt.paid > 0` — "anything is in" — true of
// the deposit only while a guest could pay nothing but a WHOLE stage. £20 of a
// £160 deposit flipped the ask to the BALANCE and quoted the whole remainder:
// the over-ask above through a new door, jumping the schedule the guest agreed
// to, and disagreeing with the SERVER, whose own default is
// booking_deposit_settled. hubAskAmount already computes that figure, so it is
// asked rather than restated. With no price summary there is nothing to derive
// it from, so that call keeps the coarse test rather than guessing.
