function settingsOpenAccom(k) {
    adminHistPush('view-settings', 'accom', { prop: k });
    const list = document.getElementById('accom-list');
    const detail = document.getElementById('accom-detail');
    if (list) list.style.display = 'none';
    if (detail) {
        detail.style.display = '';
        const arch = propertyMeta[k] && propertyMeta[k].archived;
        const priv = propertyMeta[k] && propertyMeta[k].unlisted;
        // Private (unlisted) toggle — only meaningful while the cottage is live
        // (archived cottages are already hidden). Making it public/private never
        // touches bookings, payments or history.
        const privateRow = arch
            ? ''
            : priv
              ? `<div class="settings-group" style="margin-top:14px;">
                        <button class="settings-row" ${chbAttrs('setAccommodationPrivate', String(k), false)}>
                            <span class="settings-row-ic"><svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7z"/><circle cx="12" cy="12" r="3"/></svg></span>
                            <span class="settings-row-main"><span class="settings-row-label">List on the website</span><span class="settings-row-sub">This cottage is private — show it publicly so guests can find and enquire</span></span><span class="settings-row-chev">›</span>
                        </button>
                    </div>`
              : `<div class="settings-group" style="margin-top:14px;">
                        <button class="settings-row" ${chbAttrs('setAccommodationPrivate', String(k), true)}>
                            <span class="settings-row-ic"><svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9.9 4.24A9.1 9.1 0 0 1 12 4c6.5 0 10 7 10 7a13.2 13.2 0 0 1-2.16 3.19M6.6 6.6C3.6 8.3 2 12 2 12s3.5 7 10 7a9.3 9.3 0 0 0 5.4-1.6M1 1l22 22M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg></span>
                            <span class="settings-row-main"><span class="settings-row-label">Make private</span><span class="settings-row-sub">Hide from the website but keep booking &amp; taking payments in the back office</span></span><span class="settings-row-chev">›</span>
                        </button>
                    </div>`;
        const removeRow = arch
            ? `<div class="settings-group" style="margin-top:14px;">
                        <button class="settings-row" ${chbAttrs('restoreAccommodation', String(k))}>
                            <span class="settings-row-ic"><svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5"/></svg></span>
                            <span class="settings-row-main"><span class="settings-row-label">Restore to the site</span><span class="settings-row-sub">This cottage is currently removed (hidden)</span></span><span class="settings-row-chev">›</span>
                        </button>
                    </div>`
            : `<div class="settings-group" style="margin-top:14px;">
                        <button class="settings-row" ${chbAttrs('archiveAccommodation', String(k))}>
                            <span class="settings-row-ic" style="color:var(--danger);"><svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18M8 6V4h8v2M19 6l-1 14H6L5 6"/></svg></span>
                            <span class="settings-row-main"><span class="settings-row-label" style="color:var(--danger-text);">Remove this accommodation</span><span class="settings-row-sub">Hides it from the site — bookings &amp; history are kept, and you can restore it</span></span><span class="settings-row-chev">›</span>
                        </button>
                    </div>`;
        // THE FOLD ANATOMY (the approved demo): every section is a verdict
        // fold group with its REAL editor inside — the menu→subpage hop is
        // gone, and each editor's own ids, save buttons and in-place
        // refreshes (accom-photos-<k> etc.) work unchanged inside the fold.
        // Verdicts only where a real one is cheaply derivable: the photo
        // count and the nightly rate; inventing the rest would be claims.
        const r = propertyRates[k] || defaultRates[k] || {};
        let nPhotos = 0;
        try { nPhotos = (accomImages(k) || []).length; } catch (e) {}
        const right = (id) => {
            // Verdicts only where a real one is cheaply derivable from a store
            // already in hand — an unloaded mirror mints no claim.
            try {
                if (id === 'photos') return nPhotos ? stCap('ok', nPhotos + ' photo' + (nPhotos === 1 ? '' : 's')) : stCap('unk', 'none yet');
                if (id === 'rates' && r.coupleRate) return `<span class="ac-saved" id="ac-saved-${k}">✓ Saved</span><span id="ac-fig-${k}" style="font-family:var(--font-serif);font-size:1.05rem;">${gbp(Number(r.coupleRate)).replace('.00', '')}<span style="font-size:0.75rem;color:var(--text-muted);">/night</span></span>`;
                if (id === 'text') {
                    const ams = Array.isArray(siteContent['amenities-' + k]) ? siteContent['amenities-' + k] : ((propertyContent[k] || {}).amenities || []);
                    return ams.length ? stCap('ok', ams.length + ' feature' + (ams.length === 1 ? '' : 's')) : '';
                }
                if (id === 'safety') { const n = accomSafetyList(k).length; return n ? stCap('ok', n + ' item' + (n === 1 ? '' : 's')) : stCap('unk', 'none yet'); }
                if (id === 'seasons') { const n = (propertySeasons[k] || []).length; return n ? stCap('ok', n + ' season' + (n === 1 ? '' : 's')) : ''; }
                if (id === 'faq') { const n = (Array.isArray(siteContent['faqs-' + k]) ? siteContent['faqs-' + k] : []).length; return n ? stCap('ok', n + ' answer' + (n === 1 ? '' : 's')) : stCap('unk', 'none yet'); }
                if (id === 'welcome') { const n = (Array.isArray(adminPrivateContent['welcome-' + k]) ? adminPrivateContent['welcome-' + k] : []).length; return n ? stCap('ok', n + ' section' + (n === 1 ? '' : 's')) : ''; }
                if (id === 'location') return geoVal(k) ? stCap('ok', 'Pin set') : '';
                if (id === 'arrival') return (adminPrivateContent['arrival-' + k] || '').trim() ? stCap('ok', 'Written') : '';
            } catch (e) {}
            return '';
        };
        detail.innerHTML = ACCOM_SECTIONS.map((s) => {
            const key = 'ac-' + k + '-' + s.id;
            const open = __bhubOpenFolds.has(key);
            return `<section class="bhub-card glass-panel bhub-fold-grp ac-card" data-grp="${escapeHtml(key)}">
                <button type="button" class="bhub-fold-row" ${chbAttrs('bhubFoldToggle', key)} aria-expanded="${open ? 'true' : 'false'}" aria-controls="bhub-fold-${escapeHtml(key)}">
                    <span class="bhub-fold-lbl">${s.label}<small class="bhub-fold-sub">${s.sub}</small></span>
                    <span class="bhub-fold-right">${right(s.id)}<span class="bhub-chev" aria-hidden="true">›</span></span>
                </button>
                <div class="bhub-fold" id="bhub-fold-${escapeHtml(key)}"${open ? '' : ' hidden'}><div class="acr-body">${accomSectionHtml(k, s.id)}</div></div>
            </section>`;
        // privateRow was BUILT AND NEVER INTERPOLATED — the whole make-private control
        // (a working setAccommodationPrivate, the `unlisted` column, the public site
        // honouring it) had no way in. Third time this shape has been found here: see
        // the mailbox's Sent list and the status page. The affordance IS the fix.
        }).join('') + privateRow + removeRow;
        acrSync(k, true); // paint the derived lines (quiet — no whisper on open)
    }
    const title = document.getElementById('settings-panel-title');
    if (title) title.textContent = propertyMeta[k] ? propertyMeta[k].name : k;
    settingsBackTarget = () => settingsOpen('accom');
    __settingsPath = { section: 'accom', prop: k };
    window.scrollTo({ top: 0, behavior: 'smooth' });
}
// Jump STRAIGHT to a cottage's section from anywhere (e.g. search) — reveals the
// Cottages panel and hides the cottage list first, since settingsOpenAccomSec on
// its own only fills the detail pane and assumes that chrome is already shown.
function settingsGotoAccomSec(k, sec) {
    settingsOpen('accom');
    const list = document.getElementById('accom-list');
    if (list) list.style.display = 'none';
    settingsOpenAccomSec(k, sec);
}
// A section is a FOLD on the cottage's one page now — deep links (search,
// history restore, the keysafe toggle's route) land on the page with that
// fold open and scrolled to, instead of a separate subpage.
// ---- Rates steppers + live lines. Every derived figure QUOTES the model
// (weekend = nightlyRateFor's maths, badge = renderLocalGuide's string —
// gated by equality of derivations). acrSync repaints derived TEXT only,
// never the inputs, so typing is never clobbered mid-keystroke.
function acrStep(k, field, delta) {
    const r = propertyRates[k] || defaultRates[k] || {};
    const caps = { weekendPct: 200, lastminPct: 90, lastminDays: 60 };
    let v = Math.max(0, Math.round(((parseFloat(r[field]) || 0) + (parseFloat(delta) || 0)) * 10) / 10);
    if (caps[field] != null) v = Math.min(caps[field], v);
    dpSetVal('acr-' + k + '-' + field, String(v)); // the typed .value helper
    return acrType(k, field, v);
}
async function acrType(k, field, value) {
    await updateRate(k, field, value); // the existing instant-save path
    acrSync(k);
}
function acrOta(k, value) {
    // MIRROR FIRST (the saveHostText pattern): saveContent never writes
    // siteContent, and acrSync reads the mirror — without this the badge
    // preview lagged one edit behind what was typed.
    siteContent['ota-price-' + k] = value;
    saveLocalContent('ota-price-' + k, value);
    acrSync(k);
}
function acrSync(k, quiet) {
    const r = propertyRates[k] || defaultRates[k] || {};
    const couple = parseFloat(r.coupleRate) || 0;
    const wk = document.getElementById('acr-wk-sub-' + k);
    if (wk) {
        const pct = parseFloat(r.weekendPct) || 0;
        wk.innerHTML = pct > 0
            ? `Fri &amp; Sat nights become <em>${gbp(couple * (1 + pct / 100)).replace('.00', '')}</em>`
            : 'Off — weekends price like any other night';
    }
    const lm = document.getElementById('acr-lm-sub-' + k);
    if (lm) {
        const pct = parseFloat(r.lastminPct) || 0;
        const days = parseFloat(r.lastminDays) || 0;
        const on = pct > 0 && days > 0;
        lm.className = on ? 'is-on' : '';
        lm.textContent = on
            ? `On — a stay arriving inside ${days} day${days === 1 ? '' : 's'} is ${gbp(couple * (1 - pct / 100)).replace('.00', '')}/night.`
            : 'Off — a hands-off way to fill near-term gaps. Both above 0 turns it on.';
    }
    const badge = document.getElementById('acr-badge-' + k);
    if (badge) {
        // renderLocalGuide's own gate AND its own words, verbatim.
        const ota = parseFloat(siteContent['ota-price-' + k]);
        if (ota > 0 && couple > 0 && ota > couple) {
            badge.className = 'acr-badge';
            badge.textContent = `Save ${gbp(ota - couple)}/night booking direct`;
        } else {
            badge.className = 'acr-badge is-none';
            badge.textContent = ota > 0 ? 'No badge — the Airbnb price isn\u2019t higher than yours' : 'No badge until a price is set';
        }
    }
    const fig = document.getElementById('ac-fig-' + k);
    if (fig && couple > 0) fig.innerHTML = `${gbp(couple).replace('.00', '')}<span style="font-size:0.75rem;color:var(--text-muted);">/night</span>`;
    if (!quiet) {
        const sv = document.getElementById('ac-saved-' + k);
        if (sv) {
            sv.classList.add('on');
            clearTimeout(__acrSavedT[k]);
            __acrSavedT[k] = setTimeout(() => sv.classList.remove('on'), 1500);
        }
    }
}
const __acrSavedT = {};
// The home-page-card preview mirrors what the ce- inputs hold — display only,
