// On reconnect: each saved decision is put to the owner ONCE, in their own
// words from the cottage, and executes through the normal Tier-C endpoint only
// on the OK. "Not now" keeps it for the next reconnect; a server refusal (e.g.
// the guest hasn't checked out yet) keeps it too, with the reason shown.
let __odsSweeping = false;
async function odsDepConfirmSweep() {
    // RE-ENTRANT CALLERS ARE THE NORM, NOT THE EDGE: initBackOffice runs this,
    // and chbNetUp's recovery ALSO runs initBackOffice — measured, two sweeps
    // snapshotted the same list and asked about Hannah's £75 TWICE (the server's
    // book_lock made the second OK a 409, so no money moved twice — but a
    // double ask about money leaving is exactly what this flow must never do).
    // One sweep at a time, and each item is re-checked against the LIVE list
    // before it is asked about, so an item executed elsewhere is never re-asked.
    if (__odsSweeping) return;
    __odsSweeping = true;
    try {
        await odsDepConfirmRun();
    } finally {
        __odsSweeping = false;
    }
}
async function odsDepConfirmRun() {
    const list = odsDepDecisions();
    if (!list.length) return;
    for (const d2 of list) {
        if (!odsDepDecisions().some((x) => x.dbId === d2.dbId)) continue; // settled since the snapshot
        const verb = d2.choice === 'keep' ? 'Keep' : 'Return';
        const okd = await glassDialog({
            type: 'confirm',
            message: verb + ' ' + gbp(d2.amt) + (d2.choice === 'keep' ? ' from ' : ' to ') + (d2.nm || 'the guest')
                + '? You decided this at the cottage' + (d2.note ? ' — “' + d2.note + '”' : '') + '.'
                + (d2.choice === 'keep' ? '' : ' It goes back to their card and leaves your Square balance today.'),
            okLabel: verb === 'Keep' ? 'Keep the deposit' : 'Confirm the refund',
            // The photo taken at the cottage is shown WITH the question it
            // exists to answer, and uploads with the confirmed op below.
            img: d2.photo || '',
        });
        if (!okd) continue; // kept for the next reconnect — never silently dropped
        try {
            await apiPost('bookings.php', Object.assign(
                { action: d2.choice === 'keep' ? 'keep_deposit' : 'return_deposit', id: d2.dbId, note: d2.note },
                d2.photo ? { photo_data: d2.photo } : {},
            ));
            odsDepSave(odsDepDecisions().filter((x) => x.dbId !== d2.dbId));
            toast(d2.choice === 'keep' ? 'Deposit kept — booked as income.' : gbp(d2.amt) + ' on its way back to ' + (d2.nm || 'the guest') + '.');
        } catch (e) {
            // The server refused (not checked out yet, already settled…) — the
            // decision stays saved and the reason is the server's own sentence.
            toast('Not done — ' + String((e && e.message) || 'the server refused').slice(0, 140));
        }
    }
}
