let __odsPatienceUsed = false; // the boot's patience window — armed once per page
async function initBackOffice() {
    // The page header carries the living date ("Friday 10 July") instantly;
    // once the data lands, todayOpsLine() enriches it with the day's ops.
    const td = document.getElementById('today-date');
    if (td) td.textContent = chbNow().toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
    // Unlock the encrypted phone-side stores BEFORE anything reads them — the
    // day sheet and the deposit sweep both render from the decrypted mirrors.
    try {
        await chbSecLoad();
    } catch (e) {}
    // OFFLINE MODE TAKES OVER BY ITSELF, on both triggers. A dead interface
    // (navigator.onLine false) or an already-known-off verdict gets the saved
    // sheet IMMEDIATELY; a poor signal — where nothing fails, everything
    // HANGS — gets it after a short patience window instead of after the 15s
    // timeouts. loadData keeps running underneath either way: if the slow data
    // eventually lands, the success branch below swaps the sheet for the live
    // Today by itself (the same no-reload recovery chbNetUp uses). Only while
    // the stores are EMPTY — with last-good data in memory, Today is already
    // the better screen and the sheet stays out of the way.
    // NB PERF-8 (one data load per owner boot instead of two) was BUILT AND
    // REVERTED here. The doubling is real — measured on the real journey,
    // admin-bootstrap.php twice with five endpoints behind it — but reusing a
    // recently-successful load costs more than it buys: initBackOffice has five
    // callers and most exist to REFRESH (chbNetRecover after a dropped link, the
    // post-recovery re-init), so a time-window reuse skips the very reload they
    // are for. ui-test-needs-you caught that, reporting money against stores the
    // test had just cleared. Scoping the reuse to the first init of the page then
    // recovered only one of the boot's several inits, so the win largely went too.
    // A real fix needs the refresh callers to say so explicitly rather than a
    // window guessing for them; the measurement is in the PR if anyone returns.
    const __ldrP = loadData();
    const __storesEmpty = () => !Object.keys(dbBookings || {}).some((k) => (dbBookings[k] || []).length);
    let __odsPatienceT = null;
    // ONCE PER PAGE, deliberately: the patience window is the BOOT's. A
    // mid-session re-init (recovery, openBookings) already has the live
    // verdict machinery and the bookingsDead branch below — arming the timer
    // there put the sheet up 4s into every stalled refresh, and its presence
    // made the next chbNetUp "noticed", burying the specific failure toasts
    // (measured by ui-test-poorsignal §3–§4).
    if (!__odsPatienceUsed && __storesEmpty()) {
        __odsPatienceUsed = true;
        const wait = navigator.onLine === false || chbNetIsOff() ? 0 : CHB_BOOT_PATIENCE_MS + 1000;
        __odsPatienceT = setTimeout(() => {
            if (__storesEmpty()) {
                try { renderOfflineDaySheet(); } catch (e) {}
            }
        }, wait);
    }
    const __ldr = await __ldrP;
    if (__odsPatienceT) clearTimeout(__odsPatienceT);
    // No bookings could be FETCHED and none survive in memory → the offline day
    // sheet is the truest thing this screen can say (an empty live Today would
    // report a business with no bookings, which is the poor-signal lie). A
    // successful load does the opposite half: pre-warm the snapshot and drop any
    // sheet left up from an earlier failure.
    const __bookingsDead = !!(__ldr && Array.isArray(__ldr.failed) && __ldr.failed.indexOf('bookings') !== -1)
        && !Object.keys(dbBookings).some((k) => (dbBookings[k] || []).length);
    if (__bookingsDead) {
        if (renderOfflineDaySheet()) return;
    } else if (!(__ldr && Array.isArray(__ldr.failed) && __ldr.failed.indexOf('bookings') !== -1)) {
        document.body.classList.remove('offline-snap');
        const __ods = document.getElementById('offline-daysheet');
        if (__ods) __ods.remove();
        try { chbSnapWrite(); } catch (e) {}
        // …and the coast (tides/weather) joins it async — never waited on.
        try { chbSnapCoastPatch(); } catch (e) {}
        // Deposit decisions saved at a cottage door wait here for their OK —
        // fire-and-forget, one confirm each, never silently executed.
        try { odsDepConfirmSweep(); } catch (e) {}
        // …and an un-installed Apple device gets its one A2HS nudge (below).
        try { odsA2hsNudge(); } catch (e) {}
    }
    try {
        todayOpsLine();
    } catch (e) {}
    // Refused replays (IDB, so it works offline too) → the Needs-you strip
    // repaints once the mirror lands.
    try {
        oqRefusedLoad().then(() => renderNeedsYou());
    } catch (e) {}
    // The key safe mirror — the rotation duty reads it, and the next snapshot
    // carries it to the offline morning. Fire-and-forget; a failure keeps the
    // last good copy and mints no duty from ignorance.
    try {
        keysafeLoad().then(() => renderNeedsYou());
    } catch (e) {}
    // The mail watch — new customer email raises its push/duty without the
    // owner opening the mailbox (armed once per page; timer + resume probes).
    try {
        chbMailWatch();
    } catch (e) {}
    try {
        renderNeedsYou();
    } catch (e) {}
    // Guest chats for the Needs-you strip — one fire-and-forget fetch; the
    // strip repaints when the count lands.
    try {
        apiPost('messages.php', { action: 'threads' })
            .then((r) => {
                __nyChats = (((r || {}).threads) || []).filter(msgNeedsReply).length;
                renderNeedsYou();
            })
            .catch(() => {});
    } catch (e) {}
    renderCalendar();
    try {
        renderBookings(); // the bookings workspace shares the dashboard now
    } catch (e) {}
    renderInbox();
    try {
        refreshModerationCounts();
    } catch (e) {} // pending reviews/photos/experiences (badges + today card)
    try {
        checkCronHealth();
    } catch (e) {} // warn if the daily automation stopped
    try {
        checkSystemHealth();
    } catch (e) {} // one-glance systems-health rollup pill
    try {
        await loadDepositReturns();
    } catch (e) {} // for the deposits-to-return line
    showChangeoverToasts();
    // Quietly refresh external (Airbnb/Vrbo) bookings in the background so
    // cancelled or moved dates drop off on their own. Non-blocking + throttled.
    autoSyncIcalBlocks();
}
// Owner block: hold dates for maintenance / personal use (no fake booking).
// `prefill` (optional {prop, from, to}) lets a ⌘K command open this dialog
// already filled in — "block Jollyboat next weekend" — so the owner just confirms.
async function openBlockDates(prefill) {
    const pf = prefill && typeof prefill === 'object' ? prefill : {};
    // ONE dialog: pick the cottage from a dropdown (no typed keys) and the
    // dates on the BUILT-IN calendar (a daterange field — admin mode, the
    // chosen cottage's stays shaded; never the device's blind date control).
    // THE OK BUTTON NAMES WHAT IT DOES — the house convention for a glass dialog,
    // and here it is load-bearing: the guided walkthrough's one step says "tap
    // Block", and against the default "OK" that instruction named a button the
    // dialog did not have. ui-test-coach holds the two in step.
    const vals = await glassForm('Block out dates', [
        {
            id: 'prop',
            label: 'Cottage',
            type: 'select',
            value: pf.prop && propertyMeta[pf.prop] ? pf.prop : undefined,
            options: Object.keys(propertyMeta).map((k) => ({ value: k, label: propertyMeta[k].name })),
        },
        {
            id: 'range',
            label: 'Nights to block',
            type: 'daterange',
            value: { from: pf.from || '', to: pf.to || '' },
            propFrom: 'prop',
            empty: 'Pick the nights to block',
            startHint: 'Pick the first blocked night',
            endHint: 'Now pick the morning it’s free again',
            bothMsg: 'Pick the free-again morning too',
            hint: 'The second date is the checkout morning — the cottage is free again from then.',
        },
    ], { okLabel: BLOCK_DATES_OK });
    if (vals === null) return;
    const key = (vals.prop || '').trim();
    const from = ((vals.range && vals.range.from) || '').trim();
    const to = ((vals.range && vals.range.to) || '').trim();
    if (!propertyMeta[key]) {
        glassAlert('Please pick a cottage.');
        return;
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(from) || !/^\d{4}-\d{2}-\d{2}$/.test(to)) {
        glassAlert('Please pick both dates.');
        return;
    }
    if (to <= from) {
        glassAlert('The "free again" date must be after the first blocked night.');
        return;
    }
    try {
        await apiPost('ical-import.php', {
            action: 'add_block',
            prop: key,
            check_in: from,
            check_out: to,
        });
        toast('Dates blocked.');
        await initBackOffice();
    } catch (e) {
        // THE COMMON REFUSAL IS A CLASH, and its next move is obvious: change the
        // dates. This used to concatenate the raw server message onto a bare alert —
        // no way back to the form just filled in, and (the chbActErrSay rule) a 500
        // printed a PHP fatal at the owner.
        const clash = e && (e.status === 409 || /overlap/i.test(String(e.message || '')));
        if (clash) {
            const again = await glassConfirm(
                'Those dates overlap a booking or another block, so nothing was blocked. Adjust the dates and try again?',
                'Change the dates',
            );
            if (again) return openBlockDates({ prop: key, from: from, to: to });
            return;
        }
        glassAlert(chbActErrSay(e, { label: 'block those dates' }));
    }
}

// Pull the latest external calendars and refresh the blocks shown here.
// The server-side sync deletes each feed's old blocks and re-imports only
// what's currently in the feed, so cancellations and moved dates are removed.
// Throttled to once every 10 minutes (per browser) unless forced, and it
// never blocks the UI — if a feed is slow or down we keep showing what we have.
let icalSyncing = false;
const ICAL_LAST_SYNC_KEY = 'nn-ical-last-sync';
async function autoSyncIcalBlocks(force = false) {
    if (icalSyncing || !isAuthenticated) return;
    const TEN_MIN = 10 * 60 * 1000;
    try {
        const last = parseInt(localStorage.getItem(ICAL_LAST_SYNC_KEY) || '0', 10);
        if (!force && Date.now() - last < TEN_MIN) return;
    } catch (e) {}
    icalSyncing = true;
    const btn = document.getElementById('cal-refresh-btn');
    if (btn) btn.classList.add('syncing');
    renderCalUpdated();
    try {
        await apiPost('ical-import.php', { action: 'sync' });
        try {
            localStorage.setItem(ICAL_LAST_SYNC_KEY, String(Date.now()));
        } catch (e) {}
        await loadData();
        renderCalendar();
    } catch (e) {
        // Non-fatal: a feed being unreachable shouldn't disturb the back office.
    } finally {
        icalSyncing = false;
        if (btn) btn.classList.remove('syncing');
        renderCalUpdated();
    }
}

// Human-friendly "x minutes ago" / date for the calendar's last-updated line.
function formatRelativeTime(ts) {
    const diff = Date.now() - ts;
    const mins = Math.floor(diff / 60000);
    if (mins < 1) return 'just now';
    if (mins < 60) return mins + (mins === 1 ? ' minute ago' : ' minutes ago');
    const hrs = Math.floor(mins / 60);
    if (hrs < 24) return hrs + (hrs === 1 ? ' hour ago' : ' hours ago');
    const d = new Date(ts);
    return (
        'on ' +
        d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }) +
        ' at ' +
        d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })
    );
}
// Show when the external (Airbnb/Vrbo) calendars were last refreshed.
function renderCalUpdated() {
    const el = document.getElementById('cal-updated-text');
    if (!el) return;
    if (icalSyncing) {
        el.textContent = 'Syncing…';
        return;
    }
    let last = 0;
    try {
        last = parseInt(localStorage.getItem(ICAL_LAST_SYNC_KEY) || '0', 10);
    } catch (e) {}
    // Stay quiet when the sync is recent — surface a note only when it's never
    // run or has gone stale (>12h). The refresh icon is always available.
    if (!last) el.textContent = 'External calendars not synced yet';
    else if (Date.now() - last > 12 * 3600 * 1000)
        el.textContent = 'External calendars updated ' + formatRelativeTime(last);
    else el.textContent = '';
}
// Compact relative time for the inbox list: now / 5m / 3h / Yesterday / 3 Jun.
function relTime(at) {
    const d = msgDate(at);
    if (!d) return '';
    const now = chbNow();
    const secs = (now - d) / 1000;
    if (secs < 60) return 'now';
    if (secs < 3600) return Math.floor(secs / 60) + 'm';
    const sameDay = d.toDateString() === now.toDateString();
    if (sameDay) return Math.floor(secs / 3600) + 'h';
    const y = new Date(now);
    y.setDate(now.getDate() - 1);
    if (d.toDateString() === y.toDateString()) return 'Yesterday';
    return d.toLocaleDateString('en-GB', {
        day: 'numeric',
        month: 'short',
        ...(d.getFullYear() === now.getFullYear() ? {} : { year: '2-digit' }),
    });
}
// A small colour hue derived from a name/email, so each person's avatar is
// consistently tinted (helps tell conversations apart at a glance).
function strHue(s) {
    let h = 0;
    s = String(s || '');
    for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
    return h % 360;
}
function avatarInitial(s) {
    const t = String(s || '').trim();
    return (t ? t[0] : '?').toUpperCase();
}
