// Date presets so the owner can target date-gated features (mid-stay hub,
// pre-arrival, post-stay review) — not just a far-future booking.
function tcPresetButtons() {
    return `<div style="display:flex;flex-wrap:wrap;gap:8px;">
                <button class="btn-sm btn-edit" ${chbAttrs('tcCreateBooking', 'midstay', CHB_SELF)}>Arriving today (mid-stay)</button>
                <button class="btn-sm btn-edit" ${chbAttrs('tcCreateBooking', 'prearrival', CHB_SELF)}>Pre-arrival (in 3 days)</button>
                <button class="btn-sm btn-edit" ${chbAttrs('tcCreateBooking', 'past', CHB_SELF)}>Past stay (for review)</button>
                <button class="btn-sm btn-edit" ${chbAttrs('tcCreateBooking', 'future', CHB_SELF)}>Future (+30 days)</button>
            </div>`;
}
async function tcCreateBooking(preset, btn) {
    const msg = document.getElementById('tc-bk-msg');
    const show = (t, ok) => {
        if (msg) {
            msg.style.color = ok ? 'var(--ok)' : 'var(--danger)';
            msg.textContent = t;
        }
    };
    const key = liveCottageKeys()[0];
    if (!key) {
        show('No live cottage to book against.', false);
        return;
    }
    // Was local setDate() formatted through toISOString() (UTC) — the two clocks
    // disagree between 00:00 and 01:00 BST, so a demo booking made then landed a
    // day out. One UK-anchored helper instead.
    const d = (n) => ukShiftDays(todayDashed(), n);
    let ci, co;
    if (preset === 'midstay') {
        ci = d(-1);
        co = d(2);
    } else if (preset === 'prearrival') {
        ci = d(3);
        co = d(6);
    } else if (preset === 'past') {
        ci = d(-5);
        co = d(-2);
    } else {
        ci = d(30);
        co = d(33);
    }
    if (btn) btn.disabled = true;
    show('Creating…', true);
    try {
        const r = await apiPost('bookings.php', {
            action: 'add',
            prop_key: key,
            name: 'TEST — Test Centre',
            email: tcOwnerEmail || '',
            phone: '',
            check_in: ci,
            check_out: co,
            adults: 2,
            children: 0,
            payment: 'unpaid',
            notes: '[CHB-TEST] safe to delete',
            // NO override_clash. It used to send it unconditionally, so the one
            // button in the app that creates a booking without a human reading the
            // answer could also silently overlap a real guest — and the handler
            // below already had the refusal wording ready, unreachable, because
            // the override guaranteed the server would never send it.
        });
        if (r && r.id) {
            show('Created ✓', true);
            tcRenderBooking();
        } else
            show(
                (r && r.error) ||
                    (r && r.clash ? 'Those dates clash — try again.' : "Couldn't create."),
                false,
            );
    } catch (e) {
        show(e.message || "Couldn't create.", false);
    }
    if (btn) btn.disabled = false;
}
// Skip the payment and get to what comes after it: settle a TEST booking in
// full through the same set_payment write recordPayment makes (deposit
// bundled, the cash-rail shape), so the ledgers stay coherent and the
// deposit-return / receipt / My-Stays states all become walkable.
async function tcMarkPaid(id, btn) {
    let old;
    if (btn) {
        btn.disabled = true;
        old = btn.textContent;
        btn.textContent = 'Marking…';
    }
    try {
        const body = {
            action: 'set_payment',
            id,
            payment: 'paid',
            deposit_collected: true,
            payment_date: todayDashed(),
            payment_method: 'Card',
        };
        body.op_id = chbOpFor(['set_payment', body]);
        await apiPost('bookings.php', body);
        chbOpBump();
        toast('Marked paid in full — deposit included. The pay page now reads settled.');
        try {
            await loadData();
        } catch (e) {}
        tcRenderBooking();
        return;
    } catch (e) {
        glassAlert("Couldn't mark it paid: " + (e.message || 'error'));
    }
    if (btn) {
        btn.disabled = false;
        btn.textContent = old;
    }
}
