function addReviewRow() {
    const wrap = document.getElementById('reviews-editor');
    if (wrap) wrap.insertAdjacentHTML('beforeend', reviewRowHtml(null));
}
// Populate the bulk-import dropdowns (cottages are dynamic, so build at open).
// Source defaults to Airbnb — the common case for a one-time import.
function fillReviewImportControls() {
    const propSel = document.getElementById('bulk-rev-prop');
    if (propSel)
        propSel.innerHTML =
            '<option value="">(no cottage \u2014 not shown on any cottage page)</option>' +
            Object.keys(propertyMeta)
                .map((k) => `<option value="${k}">${escapeHtml(propertyMeta[k].name)}</option>`)
                .join('');
    const srcSel = document.getElementById('bulk-rev-source');
    if (srcSel)
        srcSel.innerHTML = ['Airbnb', 'Vrbo', 'Booking.com', 'Google', 'Email', 'Guestbook', '']
            .map(
                (s) =>
                    `<option value="${s}" ${s === 'Airbnb' ? 'selected' : ''}>${s || '(no source)'}</option>`,
            )
            .join('');
    const starSel = document.getElementById('bulk-rev-stars');
    if (starSel)
        starSel.innerHTML = [5, 4, 3]
            .map((n) => `<option value="${n}">${'★'.repeat(n)}</option>`)
            .join('');
}
// One-time bulk import: parse pasted reviews (one per blank-line-separated block)
// into editable rows in #reviews-editor. Forgiving by design — the owner reviews
// every row before saving, so we favour "add something sensible" over strictness.
//   • A line that's only ★ chars or "5 stars" / "5/5" sets that review's rating.
//   • A standalone date / "2 weeks ago" / "Reviewed…" line is dropped.
//   • First remaining line → name, the rest → the review text.
//   • A single-line block becomes the review text with a blank name to fill in.
function bulkImportReviews() {
    const ta = document.getElementById('bulk-rev-text');
    const raw = ((ta && ta.value) || '').trim();
    if (!raw) {
        glassAlert('Paste your reviews into the box first.');
        return;
    }
    const prop = (document.getElementById('bulk-rev-prop') || {}).value || '';
    const source = (document.getElementById('bulk-rev-source') || {}).value || '';
    const defStars = parseInt((document.getElementById('bulk-rev-stars') || {}).value) || 5;
    const wrap = document.getElementById('reviews-editor');
    if (!wrap) return;

    const isStarLine = (l) =>
        /^[★☆\s]*★[★☆\s]*$/.test(l) || /^\s*[1-5]\s*(?:\/\s*5|stars?|★)/i.test(l);
    const starsFrom = (l) => {
        const c = (l.match(/★/g) || []).length;
        if (c) return c;
        const m = l.match(/[1-5]/);
        return m ? parseInt(m[0]) : defStars;
    };
    // A month only counts as a DATE when paired with a number (year or day) — so
    // real names like "Mark", "May", "April", "June" or "Janet" are NOT dropped.
    const MONTH =
        '(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)';
    const monthYear = new RegExp('^\\s*' + MONTH + '\\.?\\s+\\d{4}\\s*$', 'i'); // "October 2024"
    const dayMonth = new RegExp(
        '^\\s*\\d{1,2}(?:st|nd|rd|th)?\\s+' + MONTH + '(?:\\.?\\s+\\d{4})?\\s*$',
        'i',
    ); // "12 May", "2 March 2024"
    const isMetaLine = (l) =>
        monthYear.test(l) ||
        dayMonth.test(l) ||
        /^\s*\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}\s*$/.test(l) || // 12/05/2024
        /\b(?:days?|weeks?|months?|years?)\s+ago\b/i.test(l) || // "2 weeks ago"
        /^\s*(?:reviewed|stayed|response from)\b/i.test(l); // dashboard chrome

    const blocks = raw
        .split(/\n\s*\n+/)
        .map((b) => b.trim())
        .filter(Boolean);
    let added = 0;
    for (const block of blocks) {
        let lines = block
            .split('\n')
            .map((l) => l.trim())
            .filter(Boolean);
        let stars = defStars;
        const si = lines.findIndex(isStarLine);
        if (si !== -1) {
            stars = starsFrom(lines[si]);
            lines.splice(si, 1);
        }
        stars = Math.max(3, Math.min(5, stars)); // the row editor only offers 3–5
        lines = lines.filter((l) => !isMetaLine(l));
        if (!lines.length) continue;
        let name = '',
            text = '';
        if (lines.length === 1) {
            text = lines[0];
        } else {
            name = lines[0].replace(/[\s:\-–—]+$/, '').slice(0, 80);
            text = lines.slice(1).join(' ');
        }
        text = text.trim();
        if (!text) continue;
        wrap.insertAdjacentHTML('beforeend', reviewRowHtml({ name, stars, text, prop, source }));
        added++;
    }
    if (!added) {
        glassAlert(
            "Couldn't find any reviews to add — check the format: the guest's name on the first line, their review underneath, and a blank line between each one.",
        );
        return;
    }
    ta.value = '';
    toast(
        added +
            ' review' +
            (added === 1 ? '' : 's') +
            ' added below — check them over, then “Save imported reviews”.',
    );
    wrap.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}
async function saveReviews() {
    const wrap = document.getElementById('reviews-editor');
    if (!wrap) return;
    const reviews = [];
    for (const row of wrap.querySelectorAll('.review-row')) {
        const get = (f) => {
            const el = row.querySelector(`[data-rf="${f}"]`);
            return el ? el.value : '';
        };
        const text = get('text').trim();
        if (!text) continue; // empty review — skip
        reviews.push({
            name: get('name').trim(),
            stars: parseInt(get('stars')) || 5,
            text,
            prop: get('prop'),
            source: get('source'),
        });
    }
    // A REVIEW WITH NO COTTAGE APPEARS ON NO COTTAGE PAGE: renderPropReviews filters
    // r.prop === propKey, so prop:'' hides the whole section, while renderGuestWords
    // does not filter and keeps rotating it on the homepage. It also deflates that
    // cottage's COUNT and AVERAGE (measured: 6 unassigned + 2 assigned read as "2").
    // "(no cottage)" is the FIRST option in both editors, so it is what you get by not
    // choosing. This ASKS rather than refusing — the bulk-send confirm's posture.
    const stranded = reviews.filter((r) => !r.prop).length;
    if (stranded) {
        const ok = await glassConfirm(
            (stranded === 1
                ? 'One review has no cottage set.'
                : `${stranded} reviews have no cottage set.`) +
                '\n\nA review with no cottage does not appear on any cottage page, and it is left out of' +
                ' that cottage\u2019s review count and star rating. It will still show in the homepage quotes.' +
                '\n\nOK = save anyway  ·  Cancel = go back and pick a cottage',
            'Save anyway',
        );
        if (!ok) return;
    }
    try {
        await saveContent('reviews', reviews);
        siteContent.reviews = reviews;
        renderReviews();
        toast(
            stranded
                ? `Reviews saved — ${stranded} with no cottage, so not on any cottage page.`
                : 'Reviews saved.',
        );
    } catch (e) {
        glassAlert("Couldn't save reviews: " + e.message);
    }
}

// ---- Seasonal rates editor (Settings) ----
// ---- Season grid: every cottage's seasonal pricing on one screen ----
// Rows are date bands (label + start + end) shared across the grid;
// columns are the live cottages. A blank cell means that cottage simply
// has no seasonal rate for that band (its base rate applies).
function seasonGridBands() {
    const bands = new Map();
    liveCottageKeys().forEach((k) =>
        (propertySeasons[k] || []).forEach((s) => {
            const key = `${s.start_date}|${s.end_date}|${s.label || ''}`;
            if (!bands.has(key))
                bands.set(key, {
                    label: s.label || '',
                    start: s.start_date,
                    end: s.end_date,
                    rates: {},
                });
            bands.get(key).rates[k] = parseFloat(s.couple_rate);
        }),
    );
    return [...bands.values()].sort((a, b) => (a.start || '').localeCompare(b.start || ''));
}
// Each season is ONE CARD (the approved demo): serif name + remove ✕ in the head,
// the dates as pills opening the BUILT-IN calendar (openFieldDatePicker, admin mode —
// NEVER a native input[type=date]), a £-pill row per cottage, and a foot that SAYS
// what a blank price means. NB a season's end date is INCLUSIVE (coupleRateForNight:
// start <= night <= end), unlike a checkout — so the card counts nightsBetween + 1
// and the picker gets `inclusive: true` so its hint cannot state a different number.
let __sgSeq = 0; // per-card ids — survive add/remove without renumbering
let __sgRemoved = 0; // pre-existing cards deleted since render; part of the change count
function sgPillsHtml(ci, co) {
    if (ci && co)
        return `<span class="sg-dt">${fmtDate(ci)}</span><span class="sg-arr" aria-hidden="true">→</span><span class="sg-dt">${fmtDate(co)}</span>`;
    return `<span class="sg-dt sg-dt-empty">Pick the season dates</span>`;
}
function sgLenText(ci, co) {
    if (!ci || !co || co < ci) return '';
    const n = nightsBetween(ci, co) + 1; // end date inclusive — see the block comment
    return `${n} night${n === 1 ? '' : 's'}`;
}
function seasonCardHtml(b) {
    const i = __sgSeq++;
    const keys = liveCottageKeys();
    return `
                <div class="sg-band" data-sg-i="${i}"${b.isNew ? ' data-sg-new="1"' : ''}>
                    <div class="sg-head">
                        <input type="text" class="sg-name" id="sg-nm-${i}" value="${escapeHtml(b.label)}" data-sg="label" placeholder="Name this season" aria-label="Season name" ${chbInput('sgSync')}>
                        <button type="button" class="sg-del" ${chbAttrs('sgRemove', String(i))} aria-label="Remove this season everywhere" title="Remove this season everywhere"><svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button>
                    </div>
                    <input type="hidden" id="sg-ci-${i}" value="${b.start || ''}" data-orig="${b.start || ''}" data-sg="start">
                    <input type="hidden" id="sg-co-${i}" value="${b.end || ''}" data-orig="${b.end || ''}" data-sg="end">
                    <button type="button" class="sg-dates" id="sg-trig-${i}" ${chbAttrs('openSeasonDates', String(i))}>${sgPillsHtml(b.start, b.end)}</button>
                    <div class="sg-len" id="sg-len-${i}">${sgLenText(b.start, b.end)}</div>
                    <div class="sg-rows">${keys
                        .map(
                            (k) => `
                        <label class="sg-row">
                            <span class="sg-cot"><span class="legend-swatch swatch-${k}"></span>${escapeHtml(propertyMeta[k].name)}</span>
                            <span class="sg-price"><span aria-hidden="true">£</span><input type="number" min="0" step="1" placeholder="base" id="sg-p-${i}-${k}" value="${b.rates[k] || ''}" data-sg-prop="${k}" aria-label="${escapeHtml(propertyMeta[k].name)} nightly rate for this season — blank keeps the base rate" ${chbInput('sgSync')}></span>
                        </label>`,
                        )
                        .join('')}</div>
                    <div class="sg-foot" id="sg-foot-${i}" style="display:none;"></div>
                </div>`;
}
function renderSeasonGrid() {
    const wrap = document.getElementById('season-grid-wrap');
    if (!wrap) return;
    const bands = seasonGridBands();
    __sgSeq = 0;
    __sgRemoved = 0;
    wrap.innerHTML = `
                <div class="acr-cap" id="sg-count"></div>
                <div class="sg-cards" id="season-grid-body">${
                    bands.length
                        ? bands.map(seasonCardHtml).join('')
                        : seasonCardHtml({ label: '', start: '', end: '', rates: {}, isNew: true })
                }</div>
                <div class="sg-actions"><button type="button" class="sg-add" data-act="addSeasonGridRow">＋ Add a season</button></div>
                <div id="sg-savebar">
                    <span id="season-grid-msg" role="status"></span>
                    <button type="button" class="sg-save" data-act="saveSeasonGrid">Save all cottages</button>
                </div>
                <p style="font-size:0.78rem;color:var(--text-muted);margin:12px 0 0;max-width:640px;">Leave a price blank and that cottage keeps its normal base rate for those dates. Removing a card removes the season from every cottage when you save.</p>`;
    sgSync();
}
function addSeasonGridRow() {
    const body = document.getElementById('season-grid-body');
    if (!body) return;
    body.insertAdjacentHTML(
        'beforeend',
        seasonCardHtml({ label: '', start: '', end: '', rates: {}, isNew: true }),
    );
    sgSync();
    const nm = body.lastElementChild && body.lastElementChild.querySelector('.sg-name');
    if (nm instanceof HTMLElement) nm.focus();
}
function sgRemove(i) {
    const card = document.querySelector(`.sg-band[data-sg-i="${i}"]`);
    if (!card) return;
    // Only a card that EXISTED at render counts as a change — binning a blank
    // card you just added leaves nothing to save.
    if (!card.hasAttribute('data-sg-new')) __sgRemoved++;
    card.remove();
    sgSync();
}
function openSeasonDates(i) {
    openFieldDatePicker({
        ci: `sg-ci-${i}`,
        co: `sg-co-${i}`,
        trigger: `sg-trig-${i}`,
        admin: true, // owner surface: past dates pickable, no guest rules, no prices
        both: true, // half a season is not a season
        inclusive: true, // the hint counts nights the way the season will
        startHint: 'Pick the season’s first night',
        endHint: 'Now pick its last night',
        bothMsg: 'Pick the last night too',
        onDone: () => sgSync(),
    });
}
// "Changed" rides the browser's own baseline — an input's defaultValue IS the
// rendered value — so the count needs no bookkeeping beyond __sgRemoved.
// EXCEPT the hidden date fields: a hidden input's value is in the spec's
// "default" mode, so writing .value writes the ATTRIBUTE and defaultValue moves
// with it (measured — the picker's write never registered as a change). Those
// two carry their baseline in data-orig instead.
function sgChanged(id) {
    const el = /** @type {HTMLInputElement|null} */ (document.getElementById(id));
    if (!el) return false;
    const base = el.type === 'hidden' ? el.getAttribute('data-orig') || '' : el.defaultValue || '';
    return el.value.trim() !== base.trim();
}
function sgSync() {
    const body = document.getElementById('season-grid-body');
    if (!body) return;
    const keys = liveCottageKeys();
    const nm = (k) => (propertyMeta[k] && propertyMeta[k].name) || k;
    const cards = body.querySelectorAll('.sg-band');
    let changes = __sgRemoved;
    cards.forEach((card) => {
        const i = card.getAttribute('data-sg-i');
        const ci = dpVal(`sg-ci-${i}`),
            co = dpVal(`sg-co-${i}`);
        const trig = document.getElementById(`sg-trig-${i}`);
        if (trig) trig.innerHTML = sgPillsHtml(ci, co);
        const len = document.getElementById(`sg-len-${i}`);
        if (len) len.textContent = sgLenText(ci, co);
        // A moved date range is ONE change however both ends moved.
        if (sgChanged(`sg-nm-${i}`)) changes++;
        if (sgChanged(`sg-ci-${i}`) || sgChanged(`sg-co-${i}`)) changes++;
        keys.forEach((k) => {
            if (sgChanged(`sg-p-${i}-${k}`)) changes++;
        });
        // The foot names who keeps their base rate — display and arithmetic agree.
        const blank = keys.filter((k) => !dpVal(`sg-p-${i}-${k}`).trim());
        const foot = document.getElementById(`sg-foot-${i}`);
        if (foot) {
            const names = blank.map(nm);
            const list =
                names.length > 1
                    ? names.slice(0, -1).join(', ') + ' and ' + names[names.length - 1]
                    : names[0] || '';
            foot.textContent = !blank.length
                ? ''
                : blank.length === keys.length
                  ? 'No prices yet — every cottage keeps its base rate for these dates.'
                  : `${list} keep${blank.length === 1 ? 's its' : ' their'} base rate for these dates.`;
            foot.style.display = blank.length ? '' : 'none';
        }
    });
    const count = document.getElementById('sg-count');
    if (count) count.textContent = `${cards.length} season${cards.length === 1 ? '' : 's'}`;
    const msg = document.getElementById('season-grid-msg');
    if (msg) {
        msg.style.color = '';
        msg.textContent = changes ? `${changes} change${changes === 1 ? '' : 's'} to save` : 'Nothing changed yet';
    }
}
async function saveSeasonGrid() {
    const body = document.getElementById('season-grid-body');
    if (!body) return;
    const keys = liveCottageKeys();
    const perProp = {};
    keys.forEach((k) => (perProp[k] = []));
    for (const card of body.querySelectorAll('.sg-band')) {
        const get = (sel) => {
            const el = card.querySelector(sel);
            return el ? el.value.trim() : '';
        };
        const label = get('[data-sg="label"]'),
            start = get('[data-sg="start"]'),
            end = get('[data-sg="end"]');
        const rates = keys.map((k) => {
            const el = card.querySelector(`[data-sg-prop="${k}"]`);
            return { k, rate: el ? parseFloat(el.value) || 0 : 0 };
        });
        if (!start && !end && !label && rates.every((r) => !r.rate)) continue; // fully empty row
        if (!start || !end) {
            glassAlert(`"${label || 'A season'}" needs both a start and an end date.`);
            return;
        }
        if (end < start) {
            glassAlert(`"${label || 'A season'}" ends before it starts — check the dates.`);
            return;
        }
        // A SEASON WITH NO PRICE IS SAVED AS NOTHING, under "Saved for all cottages ✓".
        // Only priced rows reach perProp, so a card named and dated but unpriced — which
        // its own foot invites — was silently DISCARDED, and CLEARING an existing
        // season's prices deleted it. A third refusal beside the two above.
        if (rates.every((r) => !r.rate)) {
            glassAlert(
                `"${label || 'A season'}" has no price on any cottage, so there is nothing to save — a season is a price for some dates.` +
                    ' Give it a price on at least one cottage, or remove the card with its ✕.',
            );
            return;
        }
        rates.forEach(({ k, rate }) => {
            if (rate > 0) perProp[k].push({ label, start, end, rate });
        });
    }
    const msg = document.getElementById('season-grid-msg');
    // ONE SAVE PER COTTAGE, so the report has to be per cottage too. This used to
    // run the loop inside a single try: the second cottage failing meant the FIRST
    // was already saved and the third never attempted, and the catch then said
    // "Couldn't save" — total failure about a partial write. Same discipline as the
    // bulk chase: attempt them all, name who did not make it, never a bare "Done".
    const savedKeys = [];
    const failedKeys = [];
    for (const k of keys) {
        try {
            await apiPost('rates.php', {
                action: 'seasons_save',
                prop_key: k,
                seasons: perProp[k],
            });
            // Store in start_date order — the server returns seasons sorted
            // (rates.php GET / pricing.php get_seasons: ORDER BY start_date, id)
            // and BOTH rate resolvers are first-match (coupleRateForNight /
            // PHP), so an unsorted optimistic list made the client price an
            // overlapping band differently from the server until the next full
            // loadRates: the Add-Booking quote and card prices disagreed with
            // the snapshot that bookings.php actually stored and charged.
            propertySeasons[k] = perProp[k]
                .map((s) => ({
                    label: s.label,
                    start_date: s.start,
                    end_date: s.end,
                    couple_rate: s.rate,
                }))
                .sort((a, b) => (a.start_date < b.start_date ? -1 : a.start_date > b.start_date ? 1 : 0));
            savedKeys.push(k);
        } catch (e) {
            // The client mirror is written AFTER the await, so a cottage that failed
            // keeps its last known-good seasons — screen and server stay in step.
            failedKeys.push(k);
        }
    }
    renderCardPrices();
    updatePropPriceHeading();
    const nm = (k) => (propertyMeta[k] && propertyMeta[k].name) || k;
    const list = (ks) => ks.map(nm).join(', ');
    if (!failedKeys.length) {
        // Fresh baseline: re-render from the saved propertySeasons so the change
        // counter returns to zero (defaultValue is the render, and the render is now
        // what the server holds). After a deliberate Save, never mid-keystroke — the
        // bank-details trap doesn't apply to a tap the owner just made.
        renderSeasonGrid();
        const m2 = document.getElementById('season-grid-msg');
        if (m2) {
            m2.textContent = 'Saved for all cottages ✓';
            m2.style.color = 'var(--ok-text)';
        }
        toast('Seasonal rates saved for all cottages.');
        return;
    }
    const part = savedKeys.length
        ? `Saved for ${list(savedKeys)}, but not ${list(failedKeys)} — try again to finish.`
        : `Couldn't save any of them — ${list(failedKeys)} are unchanged.`;
    if (msg) {
        msg.textContent = part;
        msg.style.color = 'var(--warn-text)';
    }
    glassAlert(part);
}
// ---- Dashboard: warn the owner if the daily automation has stopped ----
// Reads cron-status.php (stamped by cron.php on every real run). Only the
// banner appears, and only when things are genuinely quiet, so a healthy
// site shows nothing.
async function checkCronHealth() {
    const el = document.getElementById('cron-alert');
    const pill = document.getElementById('cron-pill');
    if (!el) return;
    let d;
    try {
        // loadData's admin-bootstrap round-trip stashes the cron status (it runs
        // just before this on the dashboard), so no extra request is needed;
        // fetch directly only when it's absent.
        d = window.__cronStatusPre || (await apiGet('cron-status.php'));
    } catch (e) {
        el.style.display = 'none';
        if (pill) pill.style.display = 'none';
        return;
    }
    // Exception-only pill: healthy automation stays hidden (a green "all fine"
    // badge is just noise); it appears amber only when the daily job has gone
    // quiet. A hard failure still raises the loud banner below.
    if (pill && d) {
        if (d.stale) {
            const ago = !d.everRan
                ? 'never run'
                : d.ageHours >= 48
                  ? Math.round(d.ageHours / 24) + ' days ago'
                  : d.ageHours >= 1.5
                    ? Math.round(d.ageHours) + ' h ago'
                    : 'just now';
            pill.className = 'cron-pill warn';
            pill.innerHTML = `<span class="cron-pill-dot"></span>Automation quiet · ${ago}`;
            pill.style.display = '';
        } else {
            pill.style.display = 'none';
        }
    }
    __nyCronQuiet = !!(d && d.stale);
    try {
        renderNeedsYou();
    } catch (e) {}
    if (!d || !d.stale) {
        el.style.display = 'none';
        return;
    }
    const detail = d.everRan
        ? `last ran ${d.ageHours >= 48 ? Math.round(d.ageHours / 24) + ' days' : Math.round(d.ageHours) + ' hours'} ago`
        : 'it has never run';
    el.innerHTML = `
                <svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 9v4M12 17h.01M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z"/></svg>
                <div>
                    <strong>Your daily automation looks stopped</strong> — ${detail}. While it's off, pre-arrival emails, balance reminders, guest re-invites and weekly backups won't send.
                    <div style="margin-top:6px;font-size:0.85rem;">Check the scheduled task at your host still points at <code>cron.php</code>, then open <a data-act="navDiagnostics" style="cursor:pointer;text-decoration:underline;">Status</a>.</div>
                </div>`;
    el.style.display = '';
}
// ---- Dashboard: one-glance systems-health pill ----
// Rolls up the full Status page (diagnostics.php: DB, mail, Square, cron,
// backup, migrations, error rate …) into a single dashboard signal so trouble
// surfaces without visiting System check. Green = all clear; amber = something
// needs a look; red = a hard failure. Tap opens the full Status page. Cached
// for the session so the (heavier) diagnostics scan runs at most once per visit.
async function checkSystemHealth() {
    const pill = document.getElementById('health-pill');
    if (!pill) return;
    let d;
    try {
        const cached = sessionStorage.getItem('chb-health');
        d = cached ? JSON.parse(cached) : null;
    } catch (e) {}
    if (!d) {
        try {
            const r = await apiGet('diagnostics.php');
            d = r && r.summary ? r.summary : null;
            if (d) {
                try {
                    sessionStorage.setItem('chb-health', JSON.stringify(d));
                } catch (e) {}
            }
        } catch (e) {
            pill.style.display = 'none';
            return;
        }
    }
    if (!d) {
        pill.style.display = 'none';
        return;
    }
    const fail = d.fail || 0;
    const warn = d.warn || 0;
    if (fail > 0) {
        pill.className = 'cron-pill danger';
        pill.innerHTML = `<span class="cron-pill-dot"></span>${fail} system issue${fail === 1 ? '' : 's'} — tap to check`;
    } else if (warn > 0) {
        pill.className = 'cron-pill warn';
        pill.innerHTML = `<span class="cron-pill-dot"></span>${warn} thing${warn === 1 ? '' : 's'} need${warn === 1 ? 's' : ''} a look`;
    } else {
        // No failures and no actionable warnings (optional/off features don't
        // count) → the calm green "all clear" state.
        pill.className = 'cron-pill ok';
        pill.innerHTML = `<span class="cron-pill-dot"></span>All systems operational`;
    }
    pill.style.display = '';
}
// ---- Dashboard: recent-activity feed ----
function timeAgoLabel(at) {
    try {
        const d = new Date(String(at).replace(' ', 'T'));
        const mins = Math.max(0, Math.round((Date.now() - d.getTime()) / 60000));
        if (mins < 60) return mins <= 1 ? 'just now' : `${mins} min ago`;
        const hrs = Math.round(mins / 60);
        if (hrs < 24) return `${hrs} h ago`;
        const days = Math.round(hrs / 24);
        if (days < 8) return days === 1 ? 'yesterday' : `${days} days ago`;
        return d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
    } catch (e) {
        return '';
    }
}
