        nights: f.checkIn && f.checkOut ? String(nightsBetween(f.checkIn, f.checkOut)) : '',
        party: f.party || '',
        total: f.total != null ? gbp(f.total) : '',
        balance: f.balance != null ? gbp(f.balance) : '',
